import sys


def number_guessing():

    lower, upper = [int(x) for x in input().split()]
    tries = int(input())

    while True:
        guess = lower + 1 + (upper-lower) // 2
        sys.stdout.write('{}\n'.format(guess))
        sys.stdout.flush()
        response = input()
        if response == 'CORRECT':
            return
        elif response == 'TOO_SMALL':
            lower = guess
        elif response == 'TOO_BIG':
            upper = guess - 1
        else:
            raise RuntimeError('Got response: {}'.format(response))


if __name__ == '__main__':
    test_cases = int(input())
    for t in range(test_cases):
        number_guessing()

def solve(data):
    d1, d2 = [], []
    for i,x in enumerate(data):
        if i&1:
            d2.append(x)
        else:
            d1.append(x)
    d1.sort(reverse=True)
    d2.sort(reverse=True)
    x = d1.pop()
    for i in range(len(data)-1):
        y = d1.pop() if i&1 else d2.pop()
        if x > y:
            return i
        x = y
    return 'OK'

t = int(input().strip())
for case in range(t):
    input()
    numbers = list(map(int, input().strip().split()))
    sol = solve(numbers)
    print('Case #{0}: {1}'.format(case+1, sol))

