# Algorithms and helper functions


def heapsort(iter):
    """Heapsort implementation.

    Taken from example at https://docs.python.org/3.5/library/heapq.html
    """
    heap = []

    for v in iter:
        heappush(heap, v)

    return [heappop(heap) for i in range(len(heap))]


