def build_rect(width, height):
    mat = []
    for _ in range(width):
        mat.append([])
        for _ in range(height):
            mat[-1].append(False)
    return mat

def pretty(rect):
    s = ""
    for r in rect:
        for c in r:
            s += "#" if c else "."
        s += "|\n"
    return s


def check_neightbourhood(rect, x, y):
    r = 0
    for i in range(-1, 2):
        for j in range(-1, 2):
            if rect[x + i][y + j]:
                r += 1
    return r


def get_void(rect):
    n = 9
    idx = idj = 1

    for i, row in enumerate(rect[1:-1]):
        for j, cell in enumerate(row[1:-1]):
            r = check_neightbourhood(rect, 1 + i, 1 + j)

            if r < n:
                n = r
                idx = 1 + i
                idj = 1 + j

    return (idx, idj, n)

def go_gopher(rect):
    i, j, r = get_void(rect)
    ##print("Try at {},{}\n".format(i, j))
    ##print(pretty(rect))
    ##sys.stderr.write("Try at {},{} r{}\t".format(i, j, r))
    print(i + 2, j + 2)
    ip, jp = map(int, input().split(" "))

    if ip < 0 or jp < 0:
        sys.stderr.write("\n" + pretty(rect) + "\n")
        sys.exit(1)  # We failed :(
    elif ip == jp == 0:
        return True  # We won :)
    else:
        rect[ip - 2][jp - 2] = True
        return False


