    cases = int(input())

    for i in range(cases):
        area = int(input())

        r = []

        # Because of limits of A we know that:
        if area == 20:
            r = build_rect(5, 4)
        else:
            r = build_rect(15, 14)

        while not go_gopher(r):
            pass


