def toBin(c):
	return 1 if c == '@' else 0
 
def solve(t):
	r, c, h, v = map(int, input().strip().split())
	arr = []
	for i in range(r):
		arr.append(list(map(toBin, input().strip())))
	total_num = sum(map(sum, arr))
 
	if total_num == 0:
		return "POSSIBLE"
	elif total_num % ((h + 1) * (v + 1)) !=0:
		return "IMPOSSIBLE"
	else:
		h_cuts = [0]
		current = 0
		index = 1
		for i, row in enumerate(arr):
			current += sum(row)
			if current > index * (total_num // (h + 1)):
				return "IMPOSSIBLE"
			elif current == index * (total_num // (h + 1)):
				h_cuts.append(i + 1)
				index += 1
 
		temp_arr = list(zip(*arr))
		v_cuts = [0]
		current = 0
		index = 1
		for i, row in enumerate(temp_arr):
			current += sum(row)
			if current > index * (total_num // (v + 1)):
				return "IMPOSSIBLE"
			elif current == index * (total_num // (v + 1)):
				v_cuts.append(i + 1)
				index += 1
		val = total_num // ((h + 1) * (v + 1))
		for i in range(h + 1):
			for j in range(v + 1):
				current = 0
				for row in range(h_cuts[i], h_cuts[i + 1]):
					current += sum(arr[row][v_cuts[j]:v_cuts[j + 1]])
				if current != val:
					return "IMPOSSIBLE"
		return "POSSIBLE"

t = int(input().strip())
for i in range(1, t + 1):
	s = solve(i)
	print("Case #%d: %s" % (i, s))

