def f(R,B,C,MSPs):
    t = 1
    while(g(MSPs, R, t) < B):
        t *= 2

    t0 = t//2
    t1 = t

    while(t0+1 < t1):
        t = (t0+t1)//2
        y = g(MSPs, R, t)
        
        if y < B:
            t0 = t
        else:
            t1 = t

    return t1


def g(MSPs, R, t):
    ns = sorted([max(min((t-p)//s, m),0) for m, s, p in MSPs])
    return sum(ns[-R:])




def main():
    T = int(input())

    for i in range(T):
        R,B,C = map(int, input().split())
        MSPs = [tuple(map(int, input().split())) for i in range(C)]

        print('Case #' + str(i+1) + ': ' + str(f(R,B,C,MSPs)))


if __name__ == '__main__':
    main()

from bisect import bisect_left

class ListMock(object):
    def __init__(self, fce):
        self.fce = fce

    def __getitem__(self, item):
        return self.fce(item)


def create(receipts, resources, metal, required, used):
    raw = min(required, resources[metal])
    required -= raw
    resources[metal] -= raw
    if required == 0:
        return True
    if metal in used:
        return False
    used.add(metal)
    answer = all(create(receipts, resources, ingredient, required, used) for ingredient in receipts[metal])
    used.remove(metal)
    return answer

def verify(receipts, resources, required):
    resources = list(resources)
    return create(receipts, resources, 0, required, set())

def solve():
    no_metals = int(input())
    receipts = {i: tuple(map(lambda x: int(x) - 1, input().split())) for i in range(no_metals)}
    resources = list(map(int, input().split()))
    low = 0
    high = sum(resources)
    mock = ListMock(lambda x: not verify(receipts, resources, x))
    return bisect_left(mock, True, low, high) - 1


t = int(input())

for i in range(1, t+1):
    print("Case #{}: {}".format(i, solve()))

