import sys


def interact(n):
    # print("interact", n, file=sys.stderr )
    # popularity, qtyleft

    stock = [1]*n
    popularity = [0]*n
    for i in range(n):
        stock.append((0, 1))
    for i in range(n):
        ids = list(map(int, input().split(" ")))
        d = ids[0]
        if d==-1:
            sys.exit()
        ids = ids[1:]
        # print("ids = ", ids, file=sys.stderr)
        assert d==len(ids)
        candidates = []
        for id in ids:
            popularity[id] += 1
            if stock[id]:
                candidates.append((popularity[id], id))
        candidates.sort()
        # print("candidates = ", candidates, file=sys.stderr)
        if candidates:
            _, id = candidates[0]
            stock[id] -= 1
            print(id, flush=True)
        else:
            print(-1, flush=True)

def main():
    for t in range(int(input())):
        n =  int(input())
        interact(n)

if __name__ == '__main__':
    main()

from collections import defaultdict


def get_board_if_possible(balls, balls_landed):
    if balls_landed[0] == 0 or balls_landed[-1] == 0:
        return "", "IMPOSSIBLE"
    board = defaultdict(dict)
    ball_number = 0
    max_height = 0
    for i in range(len(balls_landed)):
        remaining = balls_landed[i]
        if balls_landed[i] == 0:
            continue
        while remaining > 0:
            if i == ball_number:
                pass
            elif ball_number < i:
                moves = abs(ball_number - i)
                max_height = max(max_height, moves)
                for x in range(moves):
                    board[ball_number + x][x] = "\\"
            elif ball_number > i:
                moves = abs(ball_number - i)
                max_height = max(max_height, moves)
                for x in range(moves):
                    board[ball_number - x][x] = "/"
            remaining -= 1
            ball_number += 1
    return turn_board_into_string(board, balls, max_height), max_height + 1


def turn_board_into_string(board, balls, max_height):
    board_string = ""
    for r in range(max_height + 1):
        for c in range(balls):
            board_string += board.get(c, {}).get(r, '.')
        board_string += '\n'
    return board_string.rstrip('\n')


def main():
    cases = int(input().strip())
    for case in range(cases):
        case_number = case + 1
        balls = int(input().strip())
        balls_landed = list(map(int, input().strip().split()))
        board, answer = get_board_if_possible(balls, balls_landed)
        print('Case #{}: {}'.format(case_number, answer))
        if board:
            print(board)

if __name__ == '__main__':
    main()

