def idx(x, y, i, j):
    return (0 if i < x else 2) + (0 if j < y else 1)

def search(board, r, c, pattern, x, y):
    sset = []
    for i in range(r):
        for j in range(c):
            if pattern[idx(x, y, i, j)] == board[i][j]:
                sset.append((i, j))
    # Connected component search
    u = 0
    while len(sset) > 0:
        comp = [sset.pop()]
        i = 0
        while i < len(comp):
            np = (comp[i][0] - 1, comp[i][1])
            if np in sset and np not in comp:
                comp.append(np)
                sset.remove(np)
            np = (comp[i][0], comp[i][1] - 1)
            if np in sset and np not in comp:
                comp.append(np)
                sset.remove(np)
            np = (comp[i][0] + 1, comp[i][1])
            if np in sset and np not in comp:
                comp.append(np)
                sset.remove(np)
            np = (comp[i][0], comp[i][1] + 1)
            if np in sset and np not in comp:
                comp.append(np)
                sset.remove(np)
            i = i + 1
        u = max(u, len(comp))
    return u

