                if board[i][j] == "B" and board[i + 1][j] == "W" and "BBWW" not in patterns:
                    patterns.append("BBWW")
                if board[i][j] == "W" and board[i + 1][j] == "B" and "WWBB" not in patterns:
                    patterns.append("WWBB")
