def dim(x):
    a = min(x)
    b = max(x)
    return (b - a + 1) // 2


def run(x, y):
    return max(dim(x), dim(y))


def main():
    t = int(input().strip())
    for i in range(t):
        n = int(input())
        x = [0] * n
        y = [0] * n
        for j in range(n):
            x[j], y[j] = map(int, input().split())
        res = run(x, y)
        print('Case #{}: {}'.format(i + 1, res))


