def read_input():
    R, C, K = map(int, input().split())
    return R, C, K

def calculate(input_args):
    r, c, k = input_args
    n = r * c
    if k == n - 1:
        return None

    ans = ''
    done = False
    for _ in range(r):
        if k:
            escape = min(c, k)
            non_escape = max(c-escape, 0)

            k -= escape
            if non_escape == 0:
                ans += ('W'*escape + '\n')
            elif non_escape == 1:
                ans += ('W'*escape + 'S' + '\n')
            else:
                ans += ('W'*escape + 'E' + 'W'*(non_escape-1) + '\n')
        else:
            if c != 1:
                ans += ('E' + 'W'*(c-1) + '\n')
            else:
                if done:
                    ans += ('N\n')
                else:
                    ans += ('S\n')
                    done = True
    return ans

def to_formated_string(s):
    if s != None:
        ans = 'POSSIBLE\n' + s
    else:
        ans = 'IMPOSSIBLE\n'
    return ans

if __name__ == '__main__':
    T = int(input())
    for case in range(1, T + 1):
        input_args = read_input()
        result = calculate(input_args)
        answer = to_formated_string(result)
        print('Case #%d:' % case, answer, end='')

