    for i in range(iter_num):
        length = int(input()) + 1
        arr_str = input().split(" ")
        arr= []
        for l in arr_str:
            arr.append(int(l))
        p = 0
        q = 1
        count = 0
        temp_post = 0
        while q < length - 1:
            if arr[q] < arr[p]:
                if arr[q + 1] > arr[q]:
                    if temp_post != 0:
                        count += 1
                    temp_post = q + 1
                    p = q + 1
                    if p == length - 1:
                        break
                    q = p + 1
                elif arr[q + 1] <= arr[q]:
                    q += 1
            elif arr[q] > arr[p]:
                if arr[q + 1] < arr[q]:
                    if temp_post != 0:
                        count += 1
                    temp_post = q + 1
                    p = q + 1
                    if p == length - 1:
                        break
                    q = p + 1
                elif arr[q + 1] >= arr[q]:
                    q += 1
            else:
                p = q
                q += 1
        print("Case #" + str(i+1) + ": " + str(count))

