def get_answer():
    x, y = map(int, input().split())
    x = abs(x)
    y = abs(y)
    y, x = min(x, y), max(x, y)
    p = [[0 for i in range(max(2, x + 1))] for j in range(max(2, y + 1))]
    p[1][0] = 3
    for i in range(1, x + 1):
        p[0][i] = (2 * p[0][i - 1] + p[1][i - 1] + 6) / 3
        p[1][i] = (2 * p[1][i - 1] + p[0][i - 1] + 6) / 3
    for i in range(1, y + 1):
        for k in [0, 1]:
            p[i][k] = p[k][i]
    for j in range(2, y + 1):
        for i in range(2, x + 1):
            p[j][i] = 1 + 0.5 * (p[j - 1][i] + p[j][i - 1])
    return p[y][x]

