class Solution(object):
    def test(self):
        t = int(readline())
        for i in range(t):
            inp = self.input_handle()
            self.output_handle(i, self.solver(*inp))

    def input_handle(self):
        N = int(readline())
        words = []
        for _ in range(N):
            words.append(readline())
        return [N, words]

    def output_handle(self, i, res):
        otpt = 'Case #{}: {}'.format(i + 1, res) 
        gprint(otpt)

    def solver(self, n, words):
        dic = {}
        for word in words:
            d = dic
            for c in word[::-1]:
                if c not in d:
                    d[c] = {}
                d = d[c]
            d['#'] = 0
        self.total = 0
        # print(dic)
        def dfs_count(d):
            if len(d) == 1 and '#' in d:
                return 1
            left = 0
            for k, v in d.items():
                if k == '#':
                    left += 1
                    continue
                left += dfs_count(v)
            if left >= 2:
                left -= 2
                self.total += 2
            return left
        for v in dic.values():
            dfs_count(v)
        return self.total
S = Solution()
S.test()

