# O(P^2). Done 0:28
def best(q, xmin, xmax):
    if len(xmin)==0 and len(xmax)==0:
        return 0
    candidates = sorted(set(xmin + xmax + [0, q]))

    bestPos = 0
    bestScore = 0
    for i in candidates:
        score = 0
        for j in xmin:
            if j <= i:
                score +=1
        for j in xmax:
            if j >= i:
                score +=1
        if score > bestScore:
            bestPos = i
            bestScore = score
    return bestPos


