        if di is 'E':
            xmin.append(xi + 1)
        if di is 'W':
            xmax.append(xi - 1)
    xbest = best(q, xmin, xmax)
    ybest = best(q, ymin, ymax)
    print("Case #%d: %d %d" % (ti+1, xbest, ybest))

