        main(casenum)

def search(subs, subs_valid, v, equal = False):
    low = 0
    high = subs_valid

    if equal:
        while low < high:
            mid = (low + high) // 2
            if subs[mid] >= v:
                low = mid + 1
            else:
                high = mid
    else:
        while low < high:
            mid = (low + high) // 2
            if subs[mid] > v:
                low = mid + 1
            else:
                high = mid

    return low

def main(casenum):
    n, k = readints()
    cs = readints()
    ds = readints()


    memo_right = [None] * n
    memo_left = [None] * n

    c_subs = [None] * (n + 1)
    c_subs_ind = [None] * (n + 1)
    c_subs_valid = 0

    d_subs = [None] * (n + 1)
    d_subs_ind = [None] * (n + 1)
    d_subs_valid = 0

    # Scan from left to right
    for i in range(n):
        c = cs[i]
        d = ds[i]

        lc = search(c_subs, c_subs_valid, c, True)
        c_subs[lc] = c
        c_subs_ind[lc] = i
        c_subs_valid = lc + 1

        if lc > 0:
            lc_ind = c_subs_ind[lc - 1] + 1
        else:
            lc_ind = 0

        ld = search(d_subs, d_subs_valid, d)
        d_subs[ld] = d
        d_subs_ind[ld] = i
        d_subs_valid = ld + 1

        if d > c + k:
            memo_left[i] = None
            continue

        ld_low = search(d_subs, d_subs_valid, c - k, True)
        ld_high = search(d_subs, d_subs_valid, c + k + 1, True)

        if ld_low > 0:
            ld_low_ind = d_subs_ind[ld_low - 1]
        else:
            ld_low_ind = -1
        if ld_high > 0:
            ld_high_ind = d_subs_ind[ld_high - 1] + 1
        else:
            ld_high_ind = 0

        l_high_ind = max(lc_ind, ld_high_ind)
        l_low_ind = max(ld_low_ind, l_high_ind - 1)

        memo_left[i] = (l_high_ind, l_low_ind)

    # Scan from right to left
    c_subs_valid = 0
    d_subs_valid = 0

    for i_ in range(n):
        i = n - i_ - 1

        c = cs[i]
        d = ds[i]

        rc = search(c_subs, c_subs_valid, c)
        c_subs[rc] = c
        c_subs_ind[rc] = i
        c_subs_valid = rc + 1

        if rc > 0:
            rc_ind = c_subs_ind[rc - 1] - 1
        else:
            rc_ind = n - 1

        rd = search(d_subs, d_subs_valid, d)
        d_subs[rd] = d
        d_subs_ind[rd] = i
        d_subs_valid = rd + 1

        if d > c + k:
            memo_right[i] = None
            continue

        rd_low = search(d_subs, d_subs_valid, c - k, True)
        rd_high = search(d_subs, d_subs_valid, c + k + 1, True)

        if rd_low > 0:
            rd_low_ind = d_subs_ind[rd_low - 1]
        else:
            rd_low_ind = n
        if rd_high > 0:
            rd_high_ind = d_subs_ind[rd_high - 1] - 1
        else:
            rd_high_ind = n - 1

        r_high_ind = min(rc_ind, rd_high_ind)
        r_low_ind = min(rd_low_ind, r_high_ind + 1)

        memo_right[i] = (r_high_ind, r_low_ind)

    # print('                ', casenum)
    count = 0
    for i in range(n):
        ml = memo_left[i]
        mr = memo_right[i]
        if ml is None or mr is None:
            # print('                ', i, None)
            continue

        la, lb = ml
        ra, rb = mr

        s = (i + 1 - la) * (ra + 1 - i) - (i - lb) * (rb - i)
        # print('                ', i, s, la, lb, ra, rb)
        count += s

    printcase(casenum, count)

run(main)

class RTSolver(object):
    def __init__(self):
        self.r, self.c = map(int, input().split())

        self.mtx = []
        for _ in range(self.r):
            self.mtx.append(input().strip())
            assert len(self.mtx[-1]) == self.c

        self.state_nimber = {}

    def get_nimber(self, state):
        if state in self.state_nimber:
            return self.state_nimber[state]
        x1, y1, x2, y2 = state
        if x1 == x2 or y1 == y2:
            return 0

        poss = set()

        # H
        for i in range(x1, x2):
            is_valid = True
            for j in range(y1, y2):
                if self.mtx[i][j] == '#':
                    is_valid = False
                    break
            if not is_valid:
                continue
            poss.add(self.get_nimber((x1, y1, i, y2)) ^ self.get_nimber((i + 1, y1, x2, y2)))

        # V
        for j in range(y1, y2):
            is_valid = True
            for i in range(x1, x2):
                if self.mtx[i][j] == '#':
                    is_valid = False
                    break
            if not is_valid:
                continue
            poss.add(self.get_nimber((x1, y1, x2, j)) ^ self.get_nimber((x1, j + 1, x2, y2)))

        ret = 0
        while ret in poss:
            ret += 1
        self.state_nimber[state] = ret
        return ret

    def solve(self):
        ans = 0

        # H
        for i in range(self.r):
            is_valid = True
            for j in range(self.c):
                if self.mtx[i][j] == '#':
                    is_valid = False
                    break
            if not is_valid:
                continue

            tmp = self.get_nimber((0, 0, i, self.c)) ^ self.get_nimber((i + 1, 0, self.r, self.c))
            if tmp == 0:
                ans += self.c

        # V
        for j in range(self.c):
            is_valid = True
            for i in range(self.r):
                if self.mtx[i][j] == '#':
                    is_valid = False
                    break
            if not is_valid:
                continue

            tmp = self.get_nimber((0, 0, self.r, j)) ^ self.get_nimber((0, j + 1, self.r, self.c))
            if tmp == 0:
                ans += self.r

        return ans


num_cases = int(input())
for case_id in range(num_cases):
    s = RTSolver()
    ans = s.solve()
    print('Case #{:d}: {}'.format(case_id + 1, ans))

import sys

def gcd(u,v):
    if v == 0:
        return u
    else:
        return gcd(v,u%v)

def count(lc,lj):
    n = len(lc)
    l = []
    for i in range(n):
        for j in range(i+1,n):
            c1 = lc[i]
            j1 = lj[i]
            c2 = lc[j]
            j2 = lj[j]
            if c1 > c2 and j1 < j2 :
                u = c1 - c2
                v = j2 - j1
                d = gcd(u,v)
                l.append([u//d,v//d])
            elif c2 > c1 and j2 < j1 :
                u = c2 - c1
                v = j1 - j2
                d = gcd(u,v)
                l.append([u//d,v//d])
    l2 = sorted(l)
    count = 1
    if len(l2) == 0:
        count = 0

    for i in range(len(l2) - 1):

        if l2[i][1] != l2[i+1][1] or l2[i][0] != l2[i+1][0]:
            count += 1
    return count





