def gcd(x,y):
	if (y == 0):
		return x
	return gcd(y,x%y)

def cmp(k1,k2):
	return k1[1]*k2[0]<k1[0]*k2[1]

def calc(n,a,b,m):
	if (b==0):
		return n*(a//m)
	if (a>=m):
		return n*(a//m)+calc(n,a%m,b,m)
	if (b>=m):
		return (n-1)*n//2*(b//m)+calc(n,a,b%m,m)
	return calc((a+b*n)//m,(a+b*n)%m,m,b)

