T = int(input())

debug = False

for case in range(1, T + 1):
    M = int(input())
    R = [(int(x[0]) - 1, int(x[1]) - 1) for x in [input().split() for _ in range(M)]]

    start = [int(x) for x in input().split()]

    if sum(start) == 0:
        print("Case #{}:".format(case), 0)
        continue

    # First: what can we make at all.

    can_make = [False]*M

    stack = [] 
    for i in range(M):
        if start[i] > 0:
            can_make[i] = True
            stack.append(i)

    while stack:
        cur = stack.pop()
        for nb in R[cur]:
            if not can_make[nb]:
                can_make[nb] = True
                stack.append(nb)

    if not can_make[0]:
        print("Case #{}:".format(case), 0)
        continue

    adj_back = [[] for _ in range(M)]

    for i, (a, b) in enumerate(R):
        adj_back[a].append(i)
        adj_back[b].append(i)

    can_make_lead = [False]*M

    can_make_lead[0] = True

    stack = [0]

    while stack:
        cur = stack.pop()
        for nb in adj_back[cur]:
            if not can_make_lead[nb]:
                can_make_lead[nb] = True
                stack.append(nb)

    # Now we pretend our graph consists only of those which can be made and which can make lead.
    # And we toposort it.

    num_children = [len([x for x in R[i] if can_make[x] and can_make_lead[x]]) for i in range(M)]

    sorted_nodes = [0]

    stack = [0]

    while stack:
        cur = stack.pop()
        for nb in adj_back[cur]:
            num_children[nb] -= 1
            if nb != 0 and num_children[nb] == 0:
                sorted_nodes.append(nb)
                stack.append(nb)

    if debug:
        print(R)
        print(can_make)
        print(can_make_lead)
        print(sorted_nodes)

    if any(can_make[i] and can_make_lead[i] and num_children[i] != 0 for i in range(1, M)):
        print("Case #{}: UNBOUNDED".format(case))
        continue

    # Here we check if you can make 2 lead from lead.

    can_make_from_lead = [False]*M

    stack = [0]

    is_unbounded = False

    while stack and not is_unbounded:
        cur = stack.pop()
        for nb in R[cur]:
            if not can_make_lead[nb]:
                continue
            if can_make_from_lead[nb]:
                is_unbounded = True
                break
            else:
                can_make_from_lead[nb] = True
                if nb != 0:
                    stack.append(nb)


    if is_unbounded:
        print("Case #{}: UNBOUNDED".format(case))
        continue


    total_amount = [0]*M

    for i in reversed(sorted_nodes):
        total_amount[i] = (sum(total_amount[j] for j in adj_back[i]) + start[i]) % (10**9 + 7)

    print("Case #{}: {}".format(case, total_amount[0]))

