            if board[i][j] == board[i + 1][j]:
                union((i, j), (i + 1, j))

    for i in range(r - 1):
        for j in range(c - 1):
            if board[i][j] == board[i + 1][j + 1] and find((i, j)) != find((i + 1, j + 1)):
                ans[i][j] = "\\"
                union((i, j), (i + 1, j + 1))
                continue
            if board[i + 1][j] == board[i][j + 1] and find((i + 1, j)) != find((i, j + 1)):
                ans[i][j] = '/'
                union((i + 1, j), (i, j + 1))
                continue

    case += 1
    if len(set([find((i, j)) for i in range(r) for j in range(c)])) > 2:
        print('Case #{}: IMPOSSIBLE'.format(case))
    else:
        print('Case #{}: POSSIBLE'.format(case))
        for row in ans:
            print(''.join(row))

