from fractions import Fraction as F

class Pt:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y
        super().__init__()

    def __add__(self, other):
        return Pt(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Pt(self.x - other.x, self.y - other.y)

    def rot(self):
        return Pt(-self.y, self.x)

    def __mul__(self, v):
        return Pt(self.x * v, self.y * v)

    def cross(self, other):
        return self.x * other.y - self.y * other.x

    __rmul__ = __mul__

    def __truediv__(self, v):
        return Pt(self.x / v, self.y / v)

    def __str__(self):
        return "({}, {})".format(self.x, self.y)

    def __repr__(self):
        return "Pt({}, {})".format((self.x), (self.y))

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

    def __ne__(self, other):
        return not (self == other)

    def tup(self):
        return self.x, self.y

def ave(pts):
    return sum(pts, Pt()) / len(pts)

def frac(x):
    return '{}/{}'.format(x.numerator, x.denominator)

def same(pts, qts):
    assert len(pts) == len(qts)
    mp = min(pts, key=lambda p: p.tup())
    mq = min(qts, key=lambda p: p.tup())
    if mp != mq: return False
    imp = next(i for i in range(len(pts)) if pts[i] == mp)
    imq = next(i for i in range(len(qts)) if qts[i] == mq)
    pts = pts[imp:] + pts[:imp]
    qts = qts[imq:] + qts[:imq]
    return pts == qts

