def find_coords(n, m, rot):
    y = -int(m * 4.2 + 5)
    x1 = -m * 2
    x2 = x1 + 1
    def foo(x):
        return rot(x, x + y + y % 2)
    def ask(x):
        return (query(*foo(x)) - query(*foo(x + 1))) * 2 - n
    xs = []
    for it in range(n):
        expected = n - 2 * it
        # print(x1, x2, expected, ask(x1), file=stderr)
        assert x1 < x2
        assert x2 - x1 == 1
        assert ask(x1) >= ask(x2)
        x2 = m * 2 + 2
        if ask(x1) == expected:
            while x2 - x1 > 1:
                x = x1 + x2 >> 1
                if ask(x1) == ask(x):
                    x1 = x
                else:
                    x2 = x
            xs.append(x2)
            x1, x2 = x2, x2 + 1
        else:
            xs.append(x1)
    return xs






def rotx(*p):
    x, y = p
    assert (x + y) % 2 == 0
    return x + y >> 1, x - y >> 1

def roty(*p):
    x, y = p
    assert (x + y) % 2 == 0
    return -x + y >> 1, x + y >> 1

