def sub(a, b):
    (ax, ay), (bx, by) = a, b
    return ax - bx, ay - by

def cross(a, b):
    (ax, ay), (bx, by) = a, b
    return ax * by - ay * bx

def polkey(pt):
    def cmp(p, q):
        p = sub(p, pt)
        q = sub(q, pt)
        return cross(q, p)
    return cmp_to_key(cmp)

def solve(pts):
    pair = [None]*len(pts)
    for it in range(len(pts) // 2):
        tpts = [p for i, p in enumerate(pts) if pair[i] is None]
        assert tpts
        mn = min(tpts)
        mni = pts.index(mn)
        opts = [p for p in tpts if p != mn]
        opts.sort(key=polkey(mn))
        mx = opts[len(opts) // 2]
        mxi = pts.index(mx)
        assert pair[mni] is None
        assert pair[mxi] is None
        pair[mni] = mxi
        pair[mxi] = mni
    assert all(x is not None for x in pair)
    return pair

