def solution(S):
    I = 0
    O = 0
    i = 0
    o = 0
    ans = 0
    for j in range(len(S)):
        if S[j] == 'I':
            I += 1
        if S[j] == 'O':
            O += 1
        if S[j] == 'i':
            i += 1
        if S[j] == 'o':
            o += 1
        if I > 0 and O > 0:
            ans += 1
            I -= 1
            O -= 1
        elif i > 0 and O > 0:
            i -= 1
            O -= 1
        elif i > 0 and o > 0:
            i -= 1
            o -= 1
        elif I > 0 and o > 0:
            I -= 1
            o -= 1

    return ans

