import sys

def area(a,b,c):
	return abs(a[0]*(b[1]-c[1])+b[0] *(c[1]-a[1])+c[0]*(a[1]-b[1]))

def isInside(a,b,c,p):
	A = area(a,b,c)
	A1 = area(p, a, b)
	A2 = area(p, a, c)
	A3 = area(p, b, c)
	return (A == A1 + A2 + A3)

def convex_area(a,b,c,p):
	A = area(a,b,c)
	A1 = area(p, a, b)
	A2 = area(p, a, c)
	A3 = area(p, b, c)
	return (A1 + A2 + A3 + A) // 2

def concave_area(a,b,c,p):
	A = area(a,b,c)
	A1 = area(p, a, b)
	A2 = area(p, a, c)
	A3 = area(p, b, c)
	return min(A1+A2, A2+A3, A1+A3)

