def find_nest(digs):
    output = []
    cur_nest = 0
    for d in digs:
        if d > cur_nest:
            output += ['(' for x in range(d-cur_nest)]
        else:
            # if cur_nest == d, then nothing added here
            output += [')' for x in range(cur_nest-d)]
        output.append(d)
        cur_nest = d
    output += [')' for x in range(cur_nest)]
    output = [str(x) for x in output]
    return ''.join(output)


