from sys import stdin

def parse_case() -> [[int]]:
    N = int(stdin.readline())
    return [parse_row(stdin.readline()) for _ in range(N)]

def parse_row(row: str) -> [int]:
    return [int(x) for x in row.split(' ')]

def schedule(activities: [[int]]) -> str:
    times = sorted((x for i, [start, end] in enumerate(activities) for x in [(i, start, 1), (i, end, -1)]), key=lambda x: (x[1], x[2]))
    S = []
    free = {'C', 'J'}
    busy = {}
    for i, _, delta in times:
        if delta == -1:
            x = busy.pop(i)
            free.add(x)
            continue
        if len(free) == 0:
            return 'IMPOSSIBLE'
        parent = free.pop()
        busy[i] = parent
        if delta == 1:
            S.append((i, parent))
    return ''.join(p for i, p in sorted(S, key=lambda x: x[0]))

def main() -> None:
    T = int(stdin.readline())
    for x in range(T):
        activities = parse_case()
        S = schedule(activities)
        print('Case #{}: {}'.format(x + 1, S))

if __name__ == "__main__":
    main()

