        if depth == n:
            trace = sum([a[i][i] for i in range(n)])
            traces.add(trace)
            solutions[trace] = deepcopy(a)
        for p in permutations(range(1, n+1)):

            if all(p[i] not in a[i][:depth] for i in range(n)):
                for i in range(n):
                    a[i][depth] = p[i]
                f(depth + 1)

    f()
    traces = sorted(traces)
    print(n, '\t', traces)
    for trace in traces:
        print()
        print(trace)
        print('', *solutions[trace], sep='\n\t')


