def list_them_2(n):

    if n == 2:
        return

    given = [[False] * n for i in range(n)]
    clues = [[-1] * n for i in range(n)]

    for i in range(n - 3):
        for k in range(3):
            j = (i + k) % (n - 3)
            given[i][j] = True
            clues[i][j] = k
    for i in range(n - 3, n):
        for j in range(n - 3, n):
            given[i][j] = True
            clues[i][j] = (i - j + 1) % 3


    print()
    print()
    for i in range(n):
        for j in range(n):
            if given[i][j]:
                print(clues[i][j], end='')
            else:
                print('-', end='')
        print()

    a = [[0] * n for i in range(n)]
    for i in range(n):
        for j in range(n):
            if given[i][j]:
                a[i][j] = clues[i][j]

    def f(step):

        if step == n * n:
            print()
            print(*a, sep='\n')
            return True

        i = step // n
        j = step % n
        if given[i][j]:
            return f(step + 1)

        for l in range(n):
            if all([l != a[i][jj] for jj in range(j)]):
                if all([l != a[ii][j] for ii in range(i)]):
                    ok = True
                    for ii in range(i, n):
                        if given[ii][j]:
                            ok &= l != clues[ii][j]
                    for jj in range(j, n):
                        if given[i][jj]:
                            ok &= l != clues[i][jj]
                    if ok:
                        a[i][j] = l
                        if f(step + 1):
                            return True
        return False
    f(0)
    print('', *a, sep='\t\n')


