dist = None
def find_matching(cell, number):
    inf = 1000
    n = len(cell)

    def bfs():
        global dist
        dist = {}
        q = []
        for u in cell:
            if pair_cell[u] is None:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = inf
        dist[None] = inf
        while q:
            u = q.pop(0)
            if dist[u] < dist[None]:
                for v in cell[u]:
                    if dist[pair_number[v]] == inf:
                        dist[pair_number[v]] = dist[u] + 1
                        q.append(pair_number[v])
        return dist[None] < inf

    def dfs(u):
        if u is None:
            return True
        for v in cell[u]:
            if dist[pair_number[v]] == dist[u] + 1:
                if dfs(pair_number[v]):
                    pair_number[v] = u
                    pair_cell[u] = v
                    return True
        dist[u] = inf
        return False


    pair_cell = {i: None for i in cell}
    pair_number = {i: None for i in number}
    while bfs():
        for u in cell:
            if pair_cell[u] is None:
                dfs(u)

    return pair_cell


traces = {}
def list_traces(stop=51):
    for i in range(1, stop):
        for j in range(1, stop):
            for k in range(j - 1, j + 2):
                if not 1 <= k < stop:
                    continue
                if i == j or i == k or j == k:
                    continue
                n_min = max([4, i, j, k])
                for n in range(n_min, stop):
                    for coef in [(n, 0, 0), (n-2, 2, 0), (n-2, 1, 1)]:
                        s = coef[0] * i + coef[1] * j + coef[2] * k
                        traces[(n, s)] = [(i, j, k), coef]

