from heapq import heappush, heappop
from functools import lru_cache


@lru_cache(None)
def adjacent(x, y):
    neigh = [
        (x - 1, y - 1),
        (x - 1, y),
        (x, y - 1),
        (x, y + 1),
        (x + 1, y),
        (x + 1, y + 1),
    ]
    return [(r, c) for r, c in neigh if r >= 0 and c >= 0 and c <= r]

@lru_cache(None)
def value(x, y):
    if y == 0 or x == y:
        return 1

    return value(x - 1, y - 1) + value(x - 1, y)

def find(target):
    if target == 1:
        return [(0, 0)]
    heap = [(target - 1, 0, 0, [(0, 0)])]
    seen = {(0, 0)}

    while heap:
        target, x, y, trace = heappop(heap)
        for r, c in adjacent(x, y):
            if (r, c) not in seen:
                seen.add((r, c))
                v = value(r, c)
                if target == v:
                    return trace + [(r, c)]
                if target > v:
                    heappush(heap, (target - v, r, c, trace + [(r, c)]))


def solve(i):
    t = int(input())
    print("Case #{}:".format(i))
    for x, y in find(t):
        print("{} {}".format(x + 1, y + 1))


for i in range(1, int(input()) + 1):
    solve(i)

dirs = [(-1, 0), (0, -1), (1, 0), (0, 1)]
def solve():
    r, c = map(int, input().split())
    grid = [[*map(int, input().split())] for i in range(r)]
    total = sum(map(sum, grid))

    adj = [[[(-1, -1)]*len(dirs) for j in range(c)] for i in range(r)]
    alive = [[True]*c for i in range(r)]
    def bad(i, j):
        assert alive[i][j]
        assert all(alive[I][J] for I, J in adj[i][j] if I != -1)
        return grid[i][j] * sum(I != -1 for I, J in adj[i][j]) < sum(grid[I][J] for I, J in adj[i][j] if I != -1)
    ans = 0
    bads = []
    for i in range(r):
        for j in range(c):
            for d, (di, dj) in enumerate(dirs):
                ni, nj = i + di, j + dj
                if 0 <= ni < r and 0 <= nj < c: adj[i][j][d] = ni, nj
            if bad(i, j): bads.append((i, j))

    while bads:
        ans += total
        cands = set()
        for i, j in bads:
            assert alive[i][j]
            cands |= {(I, J) for I, J in adj[i][j] if I != -1}
            total -= grid[i][j]
            alive[i][j] = False

        for i, j in bads:
            for d in range(4):
                I, J = adj[i][j][d]
                if I != -1:
                    assert adj[I][J][d ^ 2] == (i, j)
                    adj[I][J][d ^ 2] = adj[i][j][d ^ 2]

        bads = [(i, j) for i, j in cands if alive[i][j] and bad(i, j)]

    return ans + total

for cas in range(1, 1+int(input())):
    print("Case #{}:".format(cas), solve())

class Impossible(Exception):
    pass

def recurse_hops(x, y, hops=''):
    if not x & 1 and not y & 1:
        raise Impossible
    elif x == 1 and y == 0:
        return hops + 'E'
    elif x == 0 and y == 1:
        return hops + 'N'
    elif not x & 1:
        if ((y - 1) & 2) ^ (x & 2):
            return recurse_hops(x >> 1, (y - 1) >> 1, hops + 'N')
        else:
            return recurse_hops(x >> 1, (y + 1) >> 1, hops + 'S')
    elif not y & 1:
        if ((x - 1) & 2) ^ (y & 2):
            return recurse_hops((x - 1) >> 1, y >> 1, hops + 'E')
        else:
            return recurse_hops((x + 1) >> 1, y >> 1, hops + 'W')
    else:
        raise Impossible

def get_hops():
    X, Y = map(int, input().split())

    mapping = {
        'N': 'N',
        'E': 'E',
        'W': 'W',
        'S': 'S',
    }

    if X < 0:
        mapping['W'] = 'E'
        mapping['E'] = 'W'
    if Y < 0:
        mapping['N'] = 'S'
        mapping['S'] = 'N'
    try:
        return ''.join(mapping[c] for c in recurse_hops(abs(X), abs(Y)))
    except Impossible:
        return 'IMPOSSIBLE'


def main():
    for i in range(int(input())):
        print("Case #{index}: {hops}".format(
            index=i + 1,
            hops=get_hops(),
        ))

main()

import sys

T = int(sys.stdin.readline())
for case_number in range(1, T+1):
    N, D = map(int, sys.stdin.readline().split())
    A = sorted(map(int, sys.stdin.readline().split()))

    best = D - 1 # never more than D - 1 cuts

    for i in range(len(A)):
        for d in range(best + 1):
            # We assume that slice A[i] is cut into d + 1 slices optimally, therefore slices
            # are of size t=A[i]/(d+1) and all slices of A[i] are part of the optimal solution.
            # Moreover, we can assume that no slice can be cut in less than d + 1 cuts of the same size

            # Need to produce D - d - 1 more slices
            remaining_slices = D - (d + 1)
            new_sol = d

            # try to fill with wholly divisible slices, in increasing order of size
            for j in range(i + 1, len(A)):
                if A[j] * (d + 1) % A[i] == 0:
                    t = A[j] * (d + 1) // A[i]
                    if (remaining_slices >= t):
                        new_sol += t - 1
                        remaining_slices -= t
                    else:
                        new_sol += remaining_slices
                        remaining_slices = 0

                if new_sol > best or remaining_slices == 0:
                    break

            if new_sol > best:
                continue

            if remaining_slices != 0:
                possible_slices = 0
                for j in range(len(A)):
                    if j < i or (j > i and A[j] * (d + 1) % A[i] != 0):
                        possible_slices += A[j] * (d + 1) // A[i]
                    if possible_slices >= remaining_slices:
                        break

                if possible_slices < remaining_slices:
                    continue # impossible, skip

                # TODO: should check we have enough material for the rest...
                new_sol += remaining_slices

            if new_sol < best:
                best = new_sol

    print("Case #{}: {}".format(case_number, best))

def tri(n):
    return n*(n+1) // 2

def binarysearch(diff):
    lo = 0
    hi = 10**10
    while (lo < hi):
        mid = (lo + hi) // 2
        if tri(mid) <= diff:
            lo = mid+1
        else:
            hi = mid
    if tri(mid) <= diff:
        return mid
    else:
        return mid-1

def sumalternate(start, end):
    average = (start + end) // 2
    return average*((end - start) // 2 + 1)

def binarysearch2(start, remaining):
    lo = start // 2
    hi = 10**10
    while (lo < hi):
        mid = (lo + hi) // 2
        recovered = 2*mid + (start%2)
        if sumalternate(start, recovered) <= remaining:
            lo = mid+1
        else:
            hi = mid
    recovered = 2*mid + (start%2)
    if sumalternate(start, recovered) <= remaining:
        return recovered
    else:
        return recovered-2



t = int(input())
for case in range(t):
    l, r = map(int, input().split())
    answer = 0
    diff = abs(l - r)
    step1 = binarysearch(diff)
    answer += step1
    if l >= r:
        l -= tri(step1)
    else:
        r -= tri(step1)

    next1 = answer+1
    next2 = answer+2

    if l >= r:
        nextpile = "L"
        maxl = binarysearch2(next1, l)
        maxr = binarysearch2(next2, r)
    else:
        nextpile = "R"
        maxl = binarysearch2(next2, l)
        maxr = binarysearch2(next1, r)

    answer = max(maxl, maxr)
    if maxl > maxr:
        upperbound = "L"
    else:
        upperbound = "R"
    if upperbound == "L" and nextpile == "L":
        l -= sumalternate(next1, maxr+1)
        r -= sumalternate(next2, maxr)
    elif upperbound == "R" and nextpile == "L":
        l -= sumalternate(next1, maxl)
        r -= sumalternate(next2, maxl+1)
    elif upperbound == "L" and nextpile == "R":
        l -= sumalternate(next2, maxr+1)
        r -= sumalternate(next1, maxr)
    elif upperbound == "R" and nextpile == "R":
        l -= sumalternate(next2, maxl)
        r -= sumalternate(next1, maxl+1)

    print ("Case #{}: {} {} {}".format(case+1, answer, l, r))

from collections import namedtuple

edge = namedtuple('edge', ('u', 'v', 'i'))
edge.__reversed__ = lambda self: edge(self.v, self.u, self.i)

class graph:
    def __init__(self, n, oneway, index=1):
        self.oneway, self.index, self.adj, self.edges = oneway, index, [[] for i in range(n + index)], []
    def __len__(self): return len(self.adj) - self.index
    def __getitem__(self, u): return self.adj[u]
    def __call__(self, e): return self.edges[e]
    def __repr__(self): return repr(self.edges)
    def append(self, u, edge): self.adj[u].append(len(self.edges)); self.edges.append(edge)
    def add_edge(self, edge):
        self.append(edge.u, edge)
        if not self.oneway: self.append(edge.v, reversed(edge))

for t in range(1, int(input()) + 1):
    n, m = [int(x) for x in input().split()]
    c = [0, 0, *(int(x) for x in input().split())]
    g = graph(n, oneway=False, index=1)
    for i in range(m):
        u, v = [int(x) for x in input().split()]
        g.add_edge(edge(u, v, i))
    known = [1, *sorted((i for i in range(2, n + 1) if c[i] > 0), key=lambda i: c[i])]
    unknown = sorted((i for i in range(2, n + 1) if c[i] < 0), key=lambda i: -c[i])
    d = [0 for i in range(n + 1)]
    for i in known:
        d[i] = c[i]
    for i in unknown:
        d[i] = d[known[-c[i] - 1]] + 1
        known.append(i)
        known.sort(key=lambda i: d[i])
    U = sorted(list(range(1, n + 1)), key=lambda i: d[i])
    index = [0 for _ in range(n + 1)]
    for i in range(len(U)):
        index[U[i]] = i
    weights = [0 for _ in range(m)]
    for u in U:
        for e in g[u]:
            if index[g(e).v] < index[u]:
                weights[g(e).i] = d[u] - d[g(e).v]
                if weights[g(e).i] <= 0:
                    weights[g(e).i] = 10**6
    print('Case #', t, ': ', ' '.join(str(x) for x in weights), sep='')

def solve(s1, s2):
	n1 = len(s1)
	n2 = len(s2)
	d = [[max(i,j) for i in range(n2+1)] for j in range(n1+1)]
	prev = [[None for i in range(n2+1)] for j in range(n1+1)]
	for i in range(1,n1+1):
		for j in range(1,n2+1):
			if s1[i-1] == s2[j-1]:
				if d[i][j] >= d[i-1][j-1]:
					d[i][j] = d[i-1][j-1]
					prev[i][j] = (i-1,j-1)
			if d[i][j] >= d[i][j-1]+1:
				d[i][j] = d[i][j-1]+1
				prev[i][j] = (i,j-1)
			if d[i][j] >= d[i-1][j]+1:
				d[i][j] = d[i-1][j]+1
				prev[i][j] = (i-1,j)
			if d[i][j] >= d[i-1][j-1]+1:
				d[i][j] = d[i-1][j-1]+1
				prev[i][j] = (i-1,j-1)
	#print(d)
	#print(prev)
	D = d[-1][-1]
	cur = 0
	w = []
	i, j = n1, n2
	while cur != D//2 and i!=0 and j!=0:
		if s1[i-1] == s2[j-1]:
			w += [s2[j-1]]
			i-=1
			j-=1
		else:
			cur += 1
			i2, j2 = prev[i][j]
			if (i2, j2) == (i-1, j):
				pass
			elif (i2, j2) == (i, j-1):
				w += [s2[j-1]]
			elif (i2, j2) == (i-1, j-1):
				w += [s2[j-1]]
			i, j = i2, j2
	while cur!=D//2:
		cur += 1
		if i!=0:
			i -= 1
		if j!=0:
			w += [s2[j-1]]
			j -= 1
	while i != 0:
		w += [s1[i-1]]
		i-=1
	return ''.join(list(reversed(w)))

T = int(input())
for t in range(1, T+1):
	s1, s2 = input().split()
	print("Case #" + str(t) + ":", solve(s1,s2))

