################################################### SOLUTION

def initialize_solution():
    pass

def main():
    K,N = read()
    X = read()
    X = [X[i]-X[0] for i in range(N)]
    T = read()
    L = [X[i+1] - X[i] for i in range(N-1)] + [K - X[-1]]
    L = L + L

    # case ans=N, K odd
    try:
        if N % 2 == 1:
            s = sum(L[i] for i in range(0,N,2))
            if 2*s <= K: raise ValueError
            d = (s - K/2)
            for i in range(N):
                d = L[i] - d
                if not (0 < d < L[i+1]): raise ValueError
            return N
    except ValueError:
        pass

    # case ans=N, K even
    try:
        if N % 2 == 0:
            s = sum(L[i] for i in range(0,N,2))
            if 2*s != K: raise ValueError
            mn, mx = 0.001, L[0]-0.001
            for i in range(N):
                mn, mx = L[i+1]-mx, L[i+1]-mn
                mn, mx = max(0,mn), min(L[i+1],mx)
                if mn > mx: raise ValueError
            return N
    except ValueError:
        pass

    # case else
    res = 2*N
    for start in range(N):
        ct = 0
        processed = 0
        lmn, lmx = 0.001, L[start]-0.001
        while processed < N:
            #print(start, processed, lmn, lmx)
            lmn, lmx = 0.001, lmx-0.001
            while processed < N:
                #print(lmn, lmx)
                mn, mx = L[start+processed+1]-lmx, L[start+processed+1]-lmn
                mn, mx = max(0.001,mn), min(L[start+processed+1]-0.001,mx)
                if mn > mx: break
                processed += 1
                lmn,lmx = mn,mx
            ct += 1
        res = min(ct+N, res)
    return res

