def getImpartialOfferings(N, array):
    array.sort()
    count = [0] * len(array)
    count[0]=1
    for i in range(1, len(array)):
        if array[i - 1] == array[i]:
            count[i] = count[i - 1]
        else:
            count[i] = count[i - 1] + 1
    return sum(count)


