def get_seq(blocks):
    result = 'A'
    for i in range(len(blocks)):
        block = int(blocks[i])
        if i % 2 == 0:
            for j in range(block - 1):
                result += chr(ord('A') + j + 1)
            result += max(chr(ord('A') + block), _get_end(int(blocks[i + 1])) if i + 1 < len(blocks) else 'A')
        else:
            for j in range(ord('A') + block - 1, ord('A') - 1, -1):
                result += chr(j)
    return result

def _get_end(block):
    return chr(ord('A') + block)

