import sys

sys.setrecursionlimit(1000000)
game = ""

memo = {}


def best(player, a, b):
    if (player, a, b) not in memo:
        memo[(player, a, b)] = _best(player, a, b)
    return memo[(player, a, b)]


def _best(player, a, b):
    char = "I" if player == 0 else "O"
    sign = -1 if player == 0 else 1
    fn = max if player == 0 else min
    other = 1 - player

    if b - a == 0:
        return sign
    if game[a] != char and game[b - 1] != char:
        return sign * (b - a + 1)
    if game[a] != char:
        return best(other, a, b - 1)
    if game[b - 1] != char:
        return best(other, a + 1, b)
    if b - a > 10:
        if game[a + 1] == char:
            return best(other, a + 1, b)
        if game[b - 2] == char:
            return best(other, a, b - 1)
    if b - a < 20:
        return fn(best(other, a + 1, b), best(other, a, b - 1))

    left_streak = 0
    right_streak = 0
    while (
        left_streak < b - a - 4
        and game[a + left_streak] == char
        and game[a + left_streak + 1] != char
    ):
        left_streak += 2
    while (
        right_streak < b - a - 4
        and game[b - 1 - right_streak] == char
        and game[b - 2 - right_streak] != char
    ):
        right_streak += 2

    return fn(
        best(other, a + 1 + max(0, left_streak - 4), b),
        best(other, a, b - 1 - max(0, right_streak - 4)),
    )


def solve():
    global game, memo
    memo = {}
    game = input()
    result = best(0, 0, len(game))
    if result > 0:
        return f"I {result}"
    else:
        return f"O {-result}"


testcases = int(input())

for tt in range(testcases):
    print(f"Case #{tt+1}: {solve()}")

