def foo(x, y, s):
    #use dp

    costs = {("C","J"): x, ("J","C"): y}

    def get_cost(pre, post):
        prepost = (pre, post)
        if prepost in costs:
            return costs[prepost]
        else:
            return 0

    def min_cost(pre, middle, post, lut):
        if middle == 0:
            return (get_cost(pre, post), pre + post)
        key = (pre, middle, post)
        if key in lut:
            return lut[key]
        options = []
        for new_post in ["C", "J"]:
            (sub_cost, new_path) = min_cost(pre, middle - 1, new_post, lut)
            total_cost = sub_cost + get_cost(new_post, post)
            options.append((total_cost, new_path+new_post))
        best = None
        if options[0][0] < options[1][0]:
            best = options[0]
        else:
            best = options[1]
        lut[key] = best
        return best

    def min_cost_only(pre, middle, post):
        lut = {}
        r=min_cost(pre, middle, post, lut)[0]
        #print ((pre, middle, post, r))
        return r

    acc = 0
    i = 0

    ls = len(s)
    if ls < 2:
        return 0

    for i in range(-1, ls - 1):
        if i == -1:
            pr = ""
        else:
            if s[i] == "?":
                continue
            pr = s[i]
        j=i+1
        while (j < ls) and s[j] == "?":
            j+=1
        if j == ls:
            po=""
        else:
            po=s[j]
        m = j-i-1

        acc += min_cost_only(pr, m, po)
        if j==ls:
            break

    return acc

