# Return lst sorted with assertion that lo_pivot < hi_pivot
def sortify(lst, lo_pivot, hi_pivot):
	left = []
	mid = []
	right = []

	for x in lst:
		if x not in [lo_pivot, hi_pivot]:
			res = ask(lo_pivot, hi_pivot, x)
			if res == lo_pivot:
				left.append(x)
			elif res == x:
				mid.append(x)
			elif res == hi_pivot:
				right.append(x)
			else:
				raise AssertionError("wtf")
	return sortify_outer(left, lo_pivot, True) + [lo_pivot] + sortify_outer(mid, lo_pivot, False) + [hi_pivot] + sortify_outer(right, lo_pivot, False)

def sortify_outer(lst, hint, is_hi):
	if len(lst) <= 1: return lst
	a, b, *_ = lst
	res = ask(a, b, hint)
	assert res in [a, b]

	if (res == a) ^ is_hi:
		return sortify(lst, a, b)
	else:
		return sortify(lst, b, a)

def solve(n):
	lst = list(range(1, n + 1))
	print(*sortify(lst, 1, 2))
	sys.stdout.flush()
	assert int(input()) == 1

