def digits(n):
	return len(str(n))

def newN(n, digit):
	mult = pow(10, digit)
	addi = mult - 1
	return n * mult, addi

for t in range(1, T+1):
	N = int(input())
	arr = [int(x) for x in input().split()]

	res = 0
	prev = -1
	for i, n in enumerate(arr):
		if n > prev:
			prev = n
			continue

		ddiff = digits(prev) - digits(n)
		n, addi = newN(n, ddiff)
		if n > prev:
			res += ddiff
		elif n + addi > prev:
			n = n + addi
			if n - prev > 1:
				# prev: 798, n: 799 case
				n = prev + 1
			res += ddiff
		else:
			n *= 10
			res += (ddiff + 1)
		prev = n
	print("Case #{}: {}".format(t, res))

import math

def check_num(num, counter):
	miss = 0
	for x in counter:
		while num % x == 0:
			if counter[x] > 0:
				num //= x
				counter[x] -= 1
				miss += x
			else:
				break
		if num % x == 0 and counter[x] == 0:
			return -1
	if num == 1:
		return miss
	else:
		return -1



def solve(pair, n, t):
	s = sum(x*y for x, y in pair)
	lower = min(s-1, 4000)
	counter = {x:y for x, y in pair}
	for num in range(s, s-lower-1, -1):
		counter2 = {x:y for x, y in pair}
		miss = check_num(num, counter2)
		if num + miss == s:
			print("Case #{}: {}".format(t, num))
			return


	print("Case #{}: {}".format(t, 0))


