import sys
def read_one_line():
    return sys.stdin.readline().strip()

def flipTF(s):
    ret=''
    for c in s:
        if c=='T':
            ret+='F'
        if c=='F':
            ret+='T'
    return ret


def calc1(N,Q,inp):
    P,S=inp[0]
    ml_ans=P
    exp_score=S
    if S<Q/2:
        ml_ans=flipTF(P)
        exp_score=Q-S
    return f'{ml_ans} {exp_score}/1'

def calc2(N,Q,inp):
    P1,S1=inp[0]
    if S1<Q/2:
        P1=flipTF(P1)
        S1=Q-S1
    P2,S2=inp[1]
    if S2<Q/2:
        P2=flipTF(P2)
        S2=Q-S2

    ml_ans=P1
    exp_score=S1
    if S2>S1:
        ml_ans=P2
        exp_score=S2
    return f'{ml_ans} {exp_score}/1'

import math 
def choose(n,k):
    return math.factorial(n)//math.factorial(k)//math.factorial(n-k)

def calc3(N,Q,inp):
    assert(N==3)
    Ps=[x[0] for x in inp]
    Ss=[x[1] for x in inp]
    # do flipping
    for i in range(3):
        if Ss[i]<Q/2:
            Ps[i]=flipTF(Ps[i])
            Ss[i]=Q-Ss[i]

    sameq=sum([int(len(set([ Pj[i] for Pj in Ps ]))==1) for i in range(Q)])
    diffq=sum([int(len(set([ Pj[i] for Pj in Ps ]))==2) for i in range(Q)])
    assert(diffq+sameq==Q)#3v0 and 2v1

    # number of times each person being outlier
    transformed_arr=[[Pj[i] for Pj in Ps] for i in range(Q)]
    p0_outlier=sum([int( x[0]!=x[1] and x[0]!=x[2] ) for x in transformed_arr])
    p1_outlier=sum([int( x[1]!=x[0] and x[1]!=x[2] ) for x in transformed_arr])
    p2_outlier=sum([int( x[2]!=x[0] and x[2]!=x[1] ) for x in transformed_arr])
    assert(p0_outlier+p1_outlier+p2_outlier==diffq)
    sameq,p0_outlier,p1_outlier,p2_outlier

    # all answer probability cases:
    total_ans_count=0

    outlier_choice_cntscores={(i,j,k):0 for i in [0,1] for j in [0,1] for k in [0,1]}


    for ansmatched_sameq in range(0,sameq+1):
        samq_choice_scaling=choose(sameq,ansmatched_sameq)
        diffq_scores=[s-ansmatched_sameq for s in Ss]
        if max(diffq_scores)>diffq or min(diffq_scores)<0:
            continue
        # now, let's iterate the outlier's correctness
        # 

        Ss_offset=[x-ansmatched_sameq for x in Ss]

        for p0_oc in range(0,p0_outlier+1):
            for p1_oc in range(0,p1_outlier+1):
                p2_oc=Ss_offset[2]-(p0_outlier-p0_oc)-(p1_outlier-p1_oc)
                #p2_diffq_score=(p0_outlier-p0_oc)+(p1_outlier-p1_oc)+p2_oc == Ss_offset[2]
                if 0<=p2_oc<=p2_outlier:
                #for p2_oc in range(0,p2_outlier+1):
                    # they can't all be wrong...
                    # what's each person's score now?
                    p0_diffq_score=p0_oc+(p1_outlier-p1_oc)+(p2_outlier-p2_oc)
                    p1_diffq_score=(p0_outlier-p0_oc)+p1_oc+(p2_outlier-p2_oc)
                    p2_diffq_score=(p0_outlier-p0_oc)+(p1_outlier-p1_oc)+p2_oc
                    if [p0_diffq_score,p1_diffq_score,p2_diffq_score]!=Ss_offset:
                        continue
                    #good! found combination
                    scaling_p0=choose(p0_outlier,p0_oc)
                    scaling_p1=choose(p1_outlier,p1_oc)
                    scaling_p2=choose(p2_outlier,p2_oc)
                    total_scaling=samq_choice_scaling*scaling_p0*scaling_p1*scaling_p2
                    #print('legitimate combination:',ansmatched_sameq,p0_oc,p1_oc,p2_oc,' scaling',total_scaling)
                    total_ans_count+=(total_scaling)
                    for p0ch in [0,1]:
                        for p1ch in [0,1]:
                            for p2ch in [0,1]:
                                my_score=ansmatched_sameq
                                if p0ch==0:
                                    my_score+=(p0_outlier-p0_oc)
                                else:
                                    my_score+=p0_oc
                                if p1ch==0:
                                    my_score+=(p1_outlier-p1_oc)
                                else:
                                    my_score+=p1_oc
                                if p2ch==0:
                                    my_score+=(p2_outlier-p2_oc)
                                else:
                                    my_score+=p2_oc
                                outlier_choice_cntscores[(p0ch,p1ch,p2ch)]+=my_score * total_scaling

        #for ansmatched_diffq in range(0,diffq+1):#
    total_ans_count 
    maxkey=(0,0,0)
    for k in outlier_choice_cntscores.keys():
        if outlier_choice_cntscores[k]>outlier_choice_cntscores[maxkey]:
            maxkey=k
    best_ans_score=outlier_choice_cntscores[maxkey]
    maxkey,best_ans_score
    ret=''
    for i in range(Q):
        allans=''.join(transformed_arr[i])
        if allans=='TTT' or allans=='FFF':
            myans=allans[0]
        if allans=='TFF' or allans=='FTT':
            #outlier 0
            if maxkey[0]==0:
                myans=allans[2]
            if maxkey[0]==1:
                myans=allans[0]
        if allans=='FTF' or allans=='TFT':
            #outlier 1
            if maxkey[1]==0:
                myans=allans[2]
            if maxkey[1]==1:
                myans=allans[1]
        if allans=='FFT' or allans=='TTF':
            #outlier 2
            if maxkey[2]==0:
                myans=allans[0]
            if maxkey[2]==1:
                myans=allans[2]
        ret+=myans
    ret
    quotient=math.gcd(best_ans_score,total_ans_count)
    z,w=(best_ans_score//quotient),(total_ans_count//quotient)
    return f'{ret} {z}/{w}'

def onecase(ti):
    N,Q=read_one_line().split()
    N=int(N)
    Q=int(Q)
    inp=[]
    for i in range(N):
        Pi,Si=read_one_line().split()
        Si=int(Si)
        inp.append((Pi,Si))
    if N==1:
        ret=calc1(N,Q,inp)
    elif N==2:
        ret=calc2(N,Q,inp)
    elif N==3:
        ret=calc3(N,Q,inp)
    print('Case #%d: %s'% (ti, ret))


