import numpy as np
import math

def getint():
    return int(input())

def getarr():
    return list(map(int, input().split()))
    # return np.fromstring(input(), dtype=int, sep=" ")

def solve(n, a, b, u):
    # possible
    g = math.gcd(a, b)
    counts = [0 for i in range(g)]
    for i, e in enumerate(u):
        if e > 0:
            counts[i % g] += 1
    c = 0
    for i in range(len(counts)):
        if counts[i] > 0:
            c += 1
    if g > 1 and c > 1:
        return -1

    for i in range(n, 2000): # unit i
        dp = [0 for j in range(i)]
        dp[i-1] = 1
        for j in reversed(range(i)):
            x = dp[j] if j >= n else dp[j] - u[j]
            if x < 0:
                break
            if j-a >= 0:
                dp[j-a] += x
            if j-b >= 0:
                dp[j-b] += x
            if j == 0:
                return i
    return -1

if __name__ == "__main__":
    t = getint()
    ans = []

    for i in range(t):
        n, a, b = getarr()
        u = getarr()
        ans.append(solve(n, a, b, u))

    for i, e in enumerate(ans):
        if e < 0:
            print("Case #%d: IMPOSSIBLE" % (i+1))
        else:
            print("Case #%d: %d" % (i+1, e))

import sys
from typing import Tuple


class InputOutputBase:
    def read_line(self) -> str:
        return input()

    def write_line(self, x: str) -> None:
        print(x)
        sys.stdout.flush()

    def write(self, x: str) -> None:
        print(x, end='')
        sys.stdout.flush()


class Interactive(Exception):
    pass


class JudgeFailedUs(Exception):
    pass


class CodeJamModernBase:
    def __init__(self):
        self._decimal_precision = 7

    def _after_interactive_done(self, input_output: InputOutputBase) -> None:
        pass

    def solve_problem(self, input_output: InputOutputBase):
        n_test_cases, kws_from_start = self._n_test_cases_and_other_info_from_first_line(input_output)
        interactive = False
        for i in range(1, n_test_cases + 1):
            input_vars = self._read_input_for_case(i, input_output)
            try:
                result = self.solve_case(*input_vars, **kws_from_start)
            except Interactive:
                interactive = True
                try:
                    result = self.solve_interactively(input_output, *input_vars, **kws_from_start)
                except JudgeFailedUs:
                    return

                if result is None:
                    continue
            self._write_output_for_case(i, result, input_output)
        if interactive:
            try:
                self._after_interactive_done(input_output)
            except JudgeFailedUs:
                return


    def solve_case(self, *args, **kwargs):
        raise NotImplementedError('solve_case not implemented')

    def solve_interactively(self, input_output: InputOutputBase, *args, **kwargs):
        raise NotImplementedError('solve_case not implemented')


    def _n_test_cases_and_other_info_from_first_line(self, input_output: InputOutputBase) -> Tuple[int, dict]:
        first_line = input_output.read_line()
        return int(first_line), dict()

    def _read_input_for_case(self, i, input_output: InputOutputBase):
        raise NotImplementedError('_read_input_for_case not implemented')

    def _format_case_result(self, result) -> str:
        if result is None:
            raise Exception('Case answer should not be None')

        if isinstance(result, float):
            return ("{0:." + str(self._decimal_precision) + "f}").format(result)

        if isinstance(result, list) or isinstance(result, tuple):
            return ' '.join((self._format_case_result(x) for x in result))

        return '{0}'.format(result)

    def _write_output_for_case(self, i: int, result, input_output: InputOutputBase) -> None:
        to_output = "Case #{0}: {1}".format(i, self._format_case_result(result))

        input_output.write_line(to_output)

    def _read_line(self, input_output: InputOutputBase, split_lines=False, map_func=None):
        line = input_output.read_line()
        if split_lines:
            parts = line.split(' ')
            if map_func is not None:
                return list(map(map_func, parts))
            return parts
        elif map_func is not None:
            return map_func(line)
        return line


class ProblemC(CodeJamModernBase):
    def _n_test_cases_and_other_info_from_first_line(self, input_output: InputOutputBase) -> Tuple[int, dict]:
        first_line = input_output.read_line()
        t, n, b, p = map(int, first_line.split(' '))
        return t, {'p': p, 'n': n, 't': t, 'b': b}

    def _read_input_for_case(self, i: int, input_output: InputOutputBase):
        return ()

    def solve_case(self, *args, **kwargs):
        raise Interactive()

    def _after_interactive_done(self, input_output: InputOutputBase) -> None:
        input_output.read_line()

    def solve_interactively(self, input_output: InputOutputBase, *args, t: int = None, n: int = None, b: int = None,
                            p: int = None):
        height = [0 for _ in range(n)]
        for exchange_inx in range(n * b):
            digit = int(input_output.read_line())
            if digit == -1:
                raise JudgeFailedUs()
            if digit == 0:
                wanted = min(height)
            elif digit == 9 or (digit > 6 and exchange_inx > n * (b - 1) + (b // 2)) or (
                    digit > 7 and exchange_inx > n * (b - 1)):
                wanted = max(x for x in height if x < b)
            elif digit >= 5:
                try:
                    wanted = max(x for x in height if x < b - 1)
                except ValueError:
                    wanted = max(x for x in height if x < b)
            else:
                try:
                    highest = max(x for x in height if x < b - 2)
                except ValueError:
                    try:
                        highest = max(x for x in height if x < b - 1)
                    except ValueError:
                        wanted = max(x for x in height if x < b)
                    else:
                        if highest < b - 1:
                            wanted = highest
                        else:
                            wanted = min(height)
                else:
                    if highest < b - 1:
                        wanted = highest
                    else:
                        wanted = min(height)

            position = height.index(wanted)
            height[position] += 1
            input_output.write_line(str(position + 1))


if __name__ == "__main__":
    ProblemC().solve_problem(InputOutputBase())

