import sys
import numpy as np

def block(s):
    count = 0
    last = None
    for c in s:
        if c != last:
            count += 1
            last = c
    return count

def solve(S,E):
    if (block(S)+1)//2 < (block(E)+1)//2:
        return "IMPOSSIBLE"
    elif S == E:
        return 0
    elif E == '0':
        return block(S)
    else:
        corner = 0
        if S == '0':
            S = '1'
            corner += 1
            if E == '1':
                return 1

        if S[-1] == '1' and (block(S)+1)//2 == (block(E)+1)//2:
            S = S + '0'
            corner += 1
        Sinv = ''.join(('1' if c=='0' else '0' for c in S))

        last = None
        for i in range(len(S)):
            if last != S[i]:
                last = S[i]
                if (last == '1' and S[i:] == E[:len(S)-i]) or (last == '0' and Sinv[i:] == E[:len(S)-i]):
                    # print (i,block(S[:i]))
                    return corner + len(E) - (len(S)-i) + block(S[:i])
        return corner + len(E) + block(S)

if __name__ == "__main__":
    T = int(sys.stdin.readline())
    for _t in range(1,T+1):
        S,E = sys.stdin.readline().split()
        print("Case #{}: {}".format(_t, solve(S,E)))

