def intersection(e1, e2):
    return [min(e1[i], e2[i]) for i in range(len(e1))]


def save(cache, exercises, i, j):
    if (i, j) not in cache:
        if j - i == 1:
            cache[(i, j)] = exercises[i], 0
        else:
            inter = intersection(save(cache, exercises, i, i + 1)[0], save(cache, exercises, i + 1, j)[0])
            total_save = max([save(cache, exercises, i, k)[1] + save(cache, exercises, k, j)[1] for k in range(i + 1, j)])
            cache[(i, j)] = inter, total_save + sum(inter)
    return cache[(i, j)]


