def comp_moves(val, inp):
    sh = (inp << 8) + inp
    ans = set()
    for _ in range(8):
        ans.add(val ^ (sh & 0xFF))
        sh >>= 1
    return ans

def binary(x):
    sh = 1 << 7
    ans = []
    while sh > 0:
        if (x & sh): ans.append("1")
        else:        ans.append("0")
        sh >>= 1
    return "".join(ans)

def weight(x):
    sh = 1 << 7
    ans = 0
    while sh > 0:
        if (x & sh): ans += 1
        sh >>= 1
    return ans

def find_unique_moves():
    db = {}
    for x in range(1,256):
        rotations = tuple(sorted(list(comp_moves(0,x))))
        if rotations not in db:
            db[rotations] = x
    return db.values()
