def readNums():
    return map(lambda x: int(x), input().split(" "))


countTests = int(input())

def top(N):
    return N//2+1
def right(N):
    return top(N)+N-1
def down(N):
    return right(N)+N-1
def left(N):
    return down(N)+N-1

def baseupdate(N):
    return 4*N -4

for n in range(countTests):
    N, K = readNums()
    if K >= N**2-2 or K < N-1:
        print(f"Case #{n+1}: IMPOSSIBLE")
        continue

    diff = N**2 - 1 - K
    if diff % 2 == 1:
        print(f"Case #{n+1}: IMPOSSIBLE")
        continue

    base = 0
    nleft = N
    skips = 0
    output = ""
    while diff > 0:
        reducer = (nleft-3)//2*8
        if diff >= reducer + 6:
            skips += 1
            output += str(base+top(nleft)) + " " + str(base+baseupdate(nleft)+top(nleft-2)) + "\n"
            diff -= reducer + 6
        else:
            if diff >= reducer + 4:
                skips += 1
                output += str(base+right(nleft)) + " " + str(base+baseupdate(nleft)+right(nleft-2)) + "\n"
                diff -= reducer + 4
            else:
                if diff >= reducer + 2:
                    skips += 1
                    output += str(base+down(nleft)) + " " + str(base+baseupdate(nleft)+down(nleft-2)) + "\n"
                    diff -= reducer + 2
                else:
                    if diff >= reducer + 0:
                        skips += 1
                        output += str(base+left(nleft)) + " " + str(base+baseupdate(nleft)+left(nleft-2)) + "\n"
                        diff -= reducer + 0
        base += baseupdate(nleft)
        nleft -= 2

    print(f"Case #{n + 1}: {skips}")
    print(output, end="")

def work(R):
    s1 = set()
    for x in range(-R, R + 1):
        for y in range(-R, R + 1):
            if round((x * x + y * y) ** 0.5) <= R:
                s1.add((x, y))

    s2 = set()
    for r in range(R + 1):
        for x in range(-r, r + 1):
            y = round((r * r - x * x) ** 0.5)
            s2.add((x, y))
            s2.add((x, -y))
            s2.add((y, x))
            s2.add((-y, x))

    return len(s1 - s2), len(s1), len(s2)


def calc_s1(n):
    res = 0
    for i in range(int(n ** 0.5) + 1):
        res += int((n - i * i) ** 0.5)
    return res * 4 + 1


def calc_s2(n):
    res = 0
    for i in range(1, n + 1):
        res += round(i * (2 ** 0.5))
    return res * 4 + 1


