import sys

def write(string):
    print(string)
    sys.stdout.flush()

T,N,K = map(int,input().split())

def get_cycles(S):
    cycles = []
    elements = set()
    for s in S:
        if s in elements:
            continue
        elements.add(s)
        new_cycle = [s]
        i = S[s-1]
        while i not in elements:
            new_cycle.append(i)
            elements.add(i)
            i = S[i-1]
        cycles.append(new_cycle)
    return cycles

def reduce_cycles(cycles):
    P = 6
    new_cycles = []
    for cycle in cycles:
        if len(cycle) < 4:
            new_cycles.append(cycle)
            continue
        while len(cycle) >= P:
            new_cycles.append(cycle[:P])
            for _ in range(P):
                del cycle[0]
        if len(cycle):
            new_cycles.append(cycle)
    return new_cycles

