        colors = [None for i in range(N)]
        for color,cycle in enumerate(cycles):
            for c in cycle:
                colors[c-1] = color + 1

        write(' '.join(map(str,colors)))

        result = int(input())
        if result == 1:
            break
        if result == -1:
