def solve(R, C, A):
    seen = set()
    dq = deque()
    for r, row in enumerate(A):
        for c, val in enumerate(row):
            if val == 1:
                dq.append((r, c, 0))
                seen.add((r, c))

    if len(seen) == 0:
        return R//2 + C//2

    heights = []
    while dq:
        r,c,d = dq.popleft()
        heights.append((d, r, c))
        for nr,nc in ((r-1,c),(r,c-1),(r+1,c),(r,c+1)):
            if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in seen:
                seen.add((nr, nc))
                dq.append((nr, nc, d+1))

    heights.sort(reverse = True)
    def diameter(points):
        spread = max(points) - min(points)

    def possible(K):
        br = []
        bc = []
        biglist = []
        for d,r,c in heights:
            if d > K:
                br.append(r)
                bc.append(c)
                biglist.append((r, c))
            else:
                break
        if not biglist: return True
        mr = (max(br) + min(br))
        mc = (max(bc) + min(bc))
        if mr % 2:
            candr = [mr//2, mr//2 + 1]
        else:
            candr = [mr//2]
        if mc % 2:
            candc = [mc//2, mc//2 + 1]
        else:
            candc = [mc//2]

        return min(max( abs(mr-r) + abs(mc-c) for r,c in biglist ) for mr in candr for mc in candc) <= K

    lo, hi = 0, R+C +1
    while lo < hi:
        mi = (lo + hi ) // 2
        if possible(mi):
            hi = mi
        else:
            lo = mi + 1

    return lo


def brute(R, C, A):
    def solv(A):
        seen = set()
        dq = deque()
        for r, row in enumerate(A):
            for c, val in enumerate(row):
                if val == 1:
                    dq.append((r, c, 0))
                    seen.add((r, c))

        H = 0
        while dq:
            r,c,d = dq.popleft()
            H = max(H, d)
            for nr,nc in ((r-1,c),(r,c-1),(r+1,c),(r,c+1)):
                if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    dq.append((nr, nc, d+1))
        return H

    ans = float('inf')
    for r, row in enumerate(A):
        for c, val in enumerate(row):
            if val == 0:
                A[r][c] = 1
                ans = min(ans, solv(A))
                A[r][c] = 0
    return ans if ans < float('inf') else 0

