def calc_maxval_borders(lens, K):
    rborder={}
    rq=collections.deque()
    for i,v in enumerate(lens):
        while rq and rq[-1][1]<v:
            j,_=rq.pop()
            rborder[j]=i
        while rq and rq[0][1]>v+K:
            j,_=rq.popleft()
            rborder[j]=i
        rq.append((i,v))
    l=len(lens)
    while rq:
        j,_=rq.pop()
        rborder[j]=l
    return [rborder[i] for i in range(l)]
def calc_maxval_ranges(lens, K):
    l=len(lens)
    rborder=calc_maxval_borders(lens, K)
    lborder=[l-c-1 for c in calc_maxval_borders(lens[::-1],K)][::-1]
    return list(zip(lborder,rborder))
def calc_row_lengths(row, K):
    ranges=calc_maxval_ranges(row,K)
    ranges.sort(key=lambda r: r[1])
    row_lengths=[0]*len(row)
    for l,r in ranges[::-1]:
        for i in range(l+1,r):
            if row_lengths[i]==0:
                row_lengths[i]=r-i
            else:
                break
    return row_lengths



def calc_borders(lens):
    rborder={}
    rq=collections.deque()
    for i,v in enumerate(lens):
        while rq and rq[-1][1]>v:
            j,_=rq.pop()
            rborder[j]=i
        rq.append((i,v))
    l=len(lens)
    while rq:
        j,_=rq.pop()
        rborder[j]=l
    return [rborder[i] for i in range(l)]
def calc_ranges(lens):
    l=len(lens)
    rborder=calc_borders(lens)
    lborder=[l-c-1 for c in calc_borders(lens[::-1])][::-1]
    return list(zip(lborder,rborder))

def get_max_area(lens):
    ranges=calc_ranges(lens)
    max_area=0
    for l,r in zip(lens,ranges):
        area=(r[1]-r[0]-1)*l
        max_area=max(max_area,area)
    return max_area
def solve(case):
    grid,K=case
    row_lens=[calc_row_lengths(r,K) for r in grid]
    max_area=max([get_max_area(l) for l in zip(*row_lens)])
    return max_area






