def read_list(f):
    return [int(x) for x in read_line(f).split()]
def read_tuple(f):
    return tuple(read_list(f))

def load_single_case(f):
    _,K=read_tuple(f)
    return K,read_list(f),read_list(f)


def load_cases(f):
    n=int(f.readline())
    cases=[]
    for _ in range(n):
        cases.append(load_single_case(f))
    return cases






def get_distances(pos, cols):
    dists={}
    for p,c in zip(pos,cols):
        dists.setdefault(c,[]).append(p)
    dists=[sorted(p) for p in dists.values()]
    dists.sort(key=len,reverse=True)
    return dists

def make_with_row(dists, K, maxd):
    rows=[0],[0]
    incl=0
    for pos in dists:
        nrows=rows[0]+[maxd]*len(pos),rows[1]+[maxd]*len(pos)
        for prevn in range(min(incl+1,K+1)):
            pcost_fin=rows[0][prevn]
            pcost_nfin=rows[1][prevn]
            for n,p in enumerate(pos):
                newn=prevn+n+1
                if newn>K:
                    break
                cost_fin=min(pcost_fin+p*2,pcost_nfin+p)
                cost_nfin=pcost_nfin+p*2
                nrows[0][newn]=min(nrows[0][newn],cost_fin)
                nrows[1][newn]=min(nrows[1][newn],cost_nfin)
        rows=nrows
        incl+=len(pos)
    return rows[0][K]

def solve(case):
    K,pos,cols=case
    maxd=sum(pos)*2
    dists=get_distances(pos,cols)
    return make_with_row(dists,K,maxd)






def outcome_string(outcome):
    return "{}".format(outcome)


def save_outcomes(f, outcomes):
    for n,o in enumerate(outcomes):
        f.write("Case #{0}: {1}\n".format( n+1 , outcome_string(o) ))
def process(path_in=None, path_out=None):
    if path_out is None and path_in is not None:
        path_out=path_in.rsplit(".",1)[0]+".out"
    f_in=open(path_in) if path_in else sys.stdin
    f_out=open(path_out,"w") if path_out else sys.stdout
    try:
        cases=load_cases(f_in)
        outcomes=[solve(c) for c in cases]
        save_outcomes(f_out, outcomes)
    finally:
        if path_in:
            f_in.close()
        if path_out:
            f_out.close()


