#!/usr/bin/python3

import heapq

test_cases = int(input())  # read a line with a single integer

def xor_even(n):
    even = 0
    while n>0:
        even = even ^ (n&1)
        n = n >> 1
    return even


for test_case in range(1, test_cases + 1):

    N,Q = [int(s) for s in input().strip().split(" ")]

    A = [int(s) for s in input().strip().split(" ")]

    Ae = list(map(xor_even, A))

    ones = [ i for i,n in enumerate(Ae) if n==1]
    maxOne = [-x for x in ones]
    heapq.heapify(maxOne)
    minOne = ones
    heapq.heapify(minOne)

    results = []
    while Q>0:
        Q -= 1
        p,v  = [int(s) for s in input().strip().split(" ")]
        ve = xor_even(v)
        if ve != Ae[p]:
            heapq.heappush(minOne, p)
            heapq.heappush(maxOne, -p)
        Ae[p] = ve

        if len(maxOne) % 2 == 0:
            results.append(N)
        else:
            while len(minOne) >= 2:
                m = heapq.heappop(minOne)
                if m == minOne[0]:
                    heapq.heappop(minOne)
                else:
                    heapq.heappush(minOne, m)
                    break
            while len(maxOne) >= 2:
                m = heapq.heappop(maxOne)
                if m == maxOne[0]:
                    heapq.heappop(maxOne)
                else:
                    heapq.heappush(maxOne,m)
                    break
            if len(maxOne) == 0:
                results.append(0)
            else:
                results.append(max(N - minOne[0] -1, -maxOne[0]))


    print("Case #{}: {}".format(test_case, " ".join(map(str, results))))

#!/usr/bin/env python3

import math

def read_ints():
    return list(map(int, input().split(" ")))

class Arr:
    def __init__(self, n):
        self._n = n
        self._dist_to_next = [None] * n
        self._dist_to_prev = [None] * n
        self._first = None
    def set(self, i):
        self._dist_to_next[i] = 0
        self._dist_to_prev[i] = 0
        if self._first is None:
            self._first = i
    def build(self):
        if self._first is None:
            for i in range(self._n):
                self._dist_to_next[i] = math.inf
                self._dist_to_prev[i] = math.inf
        else:
            d = None
            for _i in range(self._n-1, -1, -1):
                i = (_i+1 + self._first) % self._n
                if self._dist_to_next[i] is not None:
                    d = self._dist_to_next[i]
                else:
                    assert d is not None
                    self._dist_to_next[i] = d
                d += 1
            d = None
            for _i in range(self._n):
                i = (_i + self._first) % self._n
                if self._dist_to_prev[i] is not None:
                    d = self._dist_to_prev[i]
                else:
                    assert d is not None
                    self._dist_to_prev[i] = d
                d += 1
    def dist_to_next(self, i):
        return self._dist_to_next[i]
    def dist_to_prev(self, i):
        return self._dist_to_prev[i]

def main():
    for ti in range(int(input())):
        n, g, t = read_ints()
        guests = []
        clock = Arr(n)
        anti = Arr(n)
        for _ in range(g):
            hi, diri = input().split(" ")
            hi = int(hi) - 1
            if diri == "C":
                hi = (hi + t) % n
                clock.set(hi)
            else:
                hi = (hi - t) % n
                anti.set(hi)
            guests.append((hi, diri))
        clock.build()
        anti.build()
        clock_scores = [0] * n
        anti_scores = [0] * n
        for i in range(n):
            d_c = clock.dist_to_next(i)
            d_a = anti.dist_to_prev(i)
            if d_c <= d_a and d_c <= t:
                clock_scores[(i + d_c) % n] += 1
            if d_a <= d_c and d_a <= t:
                anti_scores[(i - d_a) % n] += 1
        ans = []
        for (hi, diri) in guests:
            if diri == "C":
                ans.append(clock_scores[hi])
            else:
                ans.append(anti_scores[hi])
        print("Case #{}: {}".format(ti+1, " ".join(map(str, ans))))

if __name__ == "__main__":
    main()

