    N,M = [int(k) for k in input().split()]

    for i in range(N):
        Graph[i] = []

    for i in range(M):
        c1,c2 = [int(k) for k in input().split()]

        Graph[c1-1].append(c2-1)
        Graph[c2-1].append(c1-1)

    seen = [0]*N
    total = 0
    regions = 0

    for i in range(N):
        if seen[i] == 0:
            seen[i] = 1
            q = [i]
            regions += 1

        while len(q) != 0:
            v = q.pop()
            for j in Graph[v]:
                if seen[j] == 0:
                    seen[j] = 1
                    total += 1
                    q.append(j)


    total += 2*(regions-1)

    print('Case #{}: {}'.format(t,total))

#!/usr/bin/env python
# -*- coding: utf-8 -*-
from math import sqrt, ceil


def prime_num(L, R):
    prime = [1]*(R-L+1)
    for i in range(2, int(sqrt(R))+1):
        for j in range(max(ceil(L/i), 2), R//i+1):
            num = i*j
            if num >=L and num <= R:
                prime[num-L] = 0
    return sum(prime) - ((2>=L) and (2<=R)) - ((1>=L) and (1<=R))

def odd_num(L, R):
    if L % 2 == 1:
        return (R-L)//2 + 1
    else:
        return (R-L+1)//2


def solve(L, R):
    m = 0
    for x in [1,2,3,4]:
        if x>=L and x <= R:
            m += 1
    L = max(5, L)
    if L <= R:
        res0 = prime_num(L, R)
        res1 = odd_num(ceil(L/2), R//2)
        res2 = prime_num(ceil(L/4), R//4)
        res3 = (8>=L) and (8<=R)
        res = res0 + res1 + res2 + res3
    else:
        res = 0
    return res+m

