for i in range(1, t + 1):
    L, R = [int(s) for s in input().split(" ")]
    print("Case #{}: {}".format(i, solve(L, R)))

from sys import stdin, stdout
def readline():
    return stdin.readline().strip()
def readline_map(f):
    return list(map(f, readline().split()))
def gprint(s):
    print(s)
    stdout.flush()

class Solution(object):
    def test(self):
        t = int(readline())
        for i in range(t):
            inp = self.input_handle()
            self.output_handle(i, self.solver(*inp))

    def input_handle(self):
        N, K = readline_map(int)
        walls = readline_map(int)
        days = []
        return [walls, K]

    def output_handle(self, i, res):
        otpt = 'Case #{}: {}'.format(i + 1, res) 
        gprint(otpt)

    def solver(self, walls, K):
        nums = set(walls)
        dic = {}
        for n in nums:
            for k in range(K + 1):
                dic[(n, k)] = 0
        k_min = [0 for _ in range(K + 1)]
        for w in walls:
            tmp = dic.copy()
            for n in nums:
                if n == w:
                    continue
                for k in range(K + 1):
                    tmp[(n, k)] = dic[(n, k)] + 1
            for k in range(K + 1):
                tmp[(w, k)] = min(k_min[k - 1] if k > 0 else float('inf'), dic[(w, k)])
            for k in range(K + 1):
                k_min[k] = min([tmp[(n, k)] for n in nums])
            dic = tmp
        return min([dic[(n, K)] for n in nums])




S = Solution()
S.test()

