			hcol[l - 1][s] = 0

		hcol[l - 1][s] += 1
		count_lst[l - 1] += 1

	for i in range(5):
		for key, val in hcol[i].items():
			result += val * (count_lst[i] - val)

	for i in range(5):
		for j in range(i + 1, 5):
			result += count_lst[i] * count_lst[j]

	#print(result)

	# Tricky part
	for i in reversed(range(5)):
		for key, val in hcol[i].items():
			for j in range(1, i + 1):
				count = 0
				for subset in combinations(key, j):
					s = frozenset(subset)

					if s in hcol[j - 1]:
						count += hcol[j - 1][s]

				#print(count, count_lst[j - 1])
				result += val * (count_lst[j - 1] - count)


	#print(count_lst)
	print('Case #{}: {}'.format((t + 1), result))

def get_max(connections, beauty, i, res, max_res, lighted):
    #print(i, res)

    if (i == len(connections)):
        max_val = max(max_res[0], res)
        max_res[0] = max_val
        return 

    conns = connections[i]

    get_max(connections, beauty, i+1, res, max_res, lighted)
    cnt = 0

    for c in conns:
        if lighted[c] == 0:
            cnt += beauty[c]
            lighted[c] = i + 1

    #if cnt > 0:
    get_max(connections, beauty, i+1, res + cnt, max_res, lighted)

    for c in conns:
        if lighted[c] == i+1:
            lighted[c] = 0


