def seta(board, a, b, ia, val):
    if a[ia] == None:
        a[ia] = val
        N = len(board)
        for r in range(N):
            c = ia - r
            if -1 < c < N:
                ib = N - 1 + r - c
                if (val+board[r][c])&1:
                    setb(board, a, b, ib, 0)
                else:
                    setb(board, a, b, ib, 1)

def setb(board, a, b, ib, val):
    if b[ib] == None:
        b[ib] = val
        N = len(board)
        for r in range(N):
            c = N -1 + r - ib
            if -1 < c < N:
                ia = r + c
                if (val+board[r][c])&1:
                    seta(board, a, b, ia, 0)
                else:
                    seta(board, a, b, ia, 1)

def dfs(board, a, b):
    if None not in a and None not in b:
        return sum(a)+sum(b)
    elif None in a:
        ia = a.index(None)
        atmp1, btmp1 = a[:], b[:]
        seta(board, atmp1, btmp1, ia, 0)
        atmp2, btmp2 = a[:], b[:]
        seta(board, atmp2, btmp2, ia, 1)
        return min(dfs(board, atmp1, btmp1), dfs(board, atmp2, btmp2))
    else:
        ib = b.index(None)
        atmp1, btmp1 = a[:], b[:]
        setb(board, atmp1, btmp1, ib, 0)
        atmp2, btmp2 = a[:], b[:]
        setb(board, atmp2, btmp2, ib, 1)
        return min(dfs(board, atmp1, btmp1), dfs(board, atmp2, btmp2))

