def func(arr, p, i, dp):
    if p == 0 or i >= len(arr):
        return 0
    if p < 0:
        return float("-inf")
    if p in dp[i]:
        return dp[i][p]
    beauty = 0
    sm = 0
    for k in range(len(arr[i]) + 1):

        rem = p - k
        if rem < 0:
            break
        beauty = max(beauty, sm + func(arr, rem, i + 1, dp))
        if k!= len(arr[i]):
            sm+=arr[i][k]
    dp[i][p] = beauty
    return dp[i][p]


