#Stable Wall

def get_unique_values(rows):
    return(list(set([letter for row in rows for letter in row])))

def get_dependencies(rows, R, C):
    #upper letter depends on lower letter
    dependencies_with_duplication = [(rows[i-1][j], rows[i][j]) for j in range(C) for i in range(1,R) if rows[i][j] != rows[i-1][j]]
    return(list(set(dependencies_with_duplication)))

def find_independent_record(dependencies, unique_values):
    for value in unique_values:
        dependencies_for_value = [dependency for dependency in dependencies if dependency[0] == value]
        if len(dependencies_for_value) == 0:
            return(value)
    return(-1)

def process_dependencies(dependencies, unique_values):
    #find an independent record, or fail
    if len(unique_values) == 1:
        return(unique_values[0])
    independent_record = find_independent_record(dependencies, unique_values)
    if independent_record == -1:
        return(-1)
    #recurse with dependencies on found record removed
    new_dependencies = [dependency for dependency in dependencies if dependency[1] != independent_record]
    new_unique_values = [value for value in unique_values if value != independent_record]
    new_processed_dependencies = process_dependencies(new_dependencies, new_unique_values)
    if new_processed_dependencies == -1:
        return(-1)
    else:
        return(independent_record + new_processed_dependencies)

T = int(input())

for i in range(1, T + 1):
    R, C = [int(x) for x in input().split()]
    rows = [list(input()) for row_index in range(R)]
