def solve(N:int, A:int, B:int, P:[int]):
    tree_A = [0] * (N+1)
    for i in range(N, 0, -1):
        tree_A[i] += 1
        if i ==1:
            break
        up = 1
        j =  P[i-2]
        if j == 1 and A == 1:
            tree_A[1] += tree_A[i]
        else:
            while i > A and j != 1:
                if up % A == 0:
                    tree_A[j] += tree_A[i]
                    break
                up += 1
                j = P[j-2]
                if j==1 and up % A == 0:
                    tree_A[j] += tree_A[i]

    tree_B = [0] * (N+1)
    for i in range(N, 0, -1):
        tree_B[i] += 1
        if i ==1:
            break
        up = 1
        j =  P[i-2]
        if j == 1 and B == 1:
            tree_B[1] += tree_B[i]
        else:
            while i > B and j != 1:
                if up % B == 0:
                    tree_B[j] += tree_B[i]
                    break
                up += 1
                j = P[j-2]
                if j==1 and up % B == 0:
                    tree_B[j] += tree_B[i]



    ret = 0
    for i in range(1, N+1):
        ret += (1- (1-tree_A[i] / N) * (1-tree_B[i]/N))
    return ret



