from functools import lru_cache
import collections
def solve(n, m, k, A):
    t = A

    @lru_cache(None)
    def helper(cur = tuple([])):
        #print('just in, cur = ', cur)
        l = len(cur)

        if l > k:
            return float('inf')
        c = collections.Counter()
        cur = list(cur)
        if l < k:
            c[tuple([1] + cur)] += m - l
        for i in range(l - 1, - 1, -1):
            v = cur[i]
            if v > A[i - l]:
                return float('inf')
            else:
                cur[i] += 1
                if i < l - 1 and cur[i] > cur[i + 1]:
                    c[tuple(sorted(cur))] += 1
                else:
                    c[tuple(cur)] += 1
                cur[i] -= 1
        if sum(cur) == n:

            return 0
        ans = 0
        nouse = m
        #print('cur = ', cur, 'counter c = ', c)
        for state, num in c.items():
            val = helper(state)
            if val == float('inf'):
                continue
            else:
                ans += num/m*(val + 1)
                nouse -= num
        #print('ans = ', ans, 'nouse = ', nouse)
        ans += nouse/m
        ans*= m/(m - nouse)
        #print('cur = ', cur, 'ans = ', ans)
        return ans
    return helper()




