        if S[i: i + 4] == 'KICK':
            kick.append(i)
        if S[i: i + 5] == 'START':
            start.append(i)
    if len(kick) == 0 or len(start) == 0:
        return 0
    else:
        res = 0
        j = 0
        while kick[0] > start[j]:
            j += 1
        i = 0
        while j < len(start):
            while i < len(kick) and kick[i] < start[j]:
                i += 1
            res += i
            j += 1
        return res


def main():
    t = int(input())
    for test in range(t):
        S = input()
        n = solution(S)
        print("Case #{}: {}".format(test + 1, n))


if __name__ == '__main__':
    main()

