def func(s):
    n = len(s)
    ans = ((5**(n-1)-1)//4)*5
    for i in range(n):
        val = int(s[i])
        if i == n-1:
            if i%2 == 0:
                ans += (val+1)//2
            else:
                ans += (val+2)//2
        else:
            if i%2 == 1:
                ans += ((val+1)//2)*(5**(n-i-1))
            else:
                ans += ((val)//2)*(5**(n-i-1))
        if val%2 == i%2:
            break
    return ans

def solution():
    l,r = map(int,input().split())
    l1 = str(l-1)
    r1 = str(r)
    val1 = func(r1)
    val2 = func(l1)
    ans = val1-val2
    print(ans,end='')
    return




