def solve(t, N, A):
    if N <= 1:
        print('Case #' + str(t) + ': '+ str(N))
        return

    diff = A[1] - A[0]
    curr = 2

    maxl = [1, 2]
    difl = [0, diff]

    for i in range(2, N):
        temp = A[i] - A[i-1]
        if temp == diff:
            curr += 1
        else:
            curr = 2
        maxl.append(curr)
        difl.append(temp)
        diff = temp

    m = max(maxl)

    for i in range(2, N):
        if maxl[i] <= maxl[i-1]:
            leng = maxl[i-1] + 1
            temp = A[i-1] + difl[i-1]
            for j in range(i+1, N):
                if A[j] == temp + difl[i-1]:
                    leng += 1
                    temp += difl[i-1]
                else:
                    break
            if leng > m:
                m = leng

    A.reverse()

    diff = A[1] - A[0]
    curr = 2

    maxl = [1, 2]
    difl = [0, diff]

    for i in range(2, N):
        temp = A[i] - A[i-1]
        if temp == diff:
            curr += 1
        else:
            curr = 2
        maxl.append(curr)
        difl.append(temp)
        diff = temp

    for i in range(2, N):
        if maxl[i] <= maxl[i-1]:
            leng = maxl[i-1] + 1
            temp = A[i-1] + difl[i-1]
            for j in range(i+1, N):
                if A[j] == temp + difl[i-1]:
                    leng += 1
                    temp += difl[i-1]
                else:
                    break
            if leng > m:
                m = leng

    print('Case #' + str(t) + ': '+ str(m))

