import math


def is_prime(num):
    bound = int(math.sqrt(num)) + 1
    for i in range(2, bound):
        if num % i == 0: return False
    return True


def next_prime(num):
    num += 1
    while not is_prime(num):
        num += 1
    return num


def secretCode(Z: int) -> int:
    sqrt = int(math.sqrt(Z))
    a = sqrt
    while not is_prime(a):
        a -= 1
    b = next_prime(a)
    while a * b > Z:
        b = a
        a -= 1
        while not is_prime(a):
            a -= 1
    return a * b


