def Count(n):
    count = 0
    i = 0
    while (i * (i + 1) < 2 * n):
        a = (1.0 * n - (i * (i + 1) ) / 2) / (i + 1)
        if (a - int(a) == 0.0):
            count += 1
        i += 1
    return count

