def solve_dyn(W,E):
    rounds = 60
    dyn = {1:{(1,0,0):(1/3*W+1/3*E,"R"),
           (0,1,0):(1/3*W+1/3*E,"P"),
           (0,0,1):(1/3*W+1/3*E,"S")
    }}

    for i in range(2,rounds+1):
        dyn[i] = {}
        for probs in dyn[i-1]:

            for dyn_i, new_play in enumerate(["R","P","S"]):
                new_probs = tuple([probs[j] if j != dyn_i else probs[j] + 1 for j in
                     range(3)])

                new_exp, old_sol = dyn[i-1][probs]
                new_exp += get_exp(probs, new_play, i, W, E)

                if new_probs in dyn[i]:
                    old_exp,_ = dyn[i][new_probs]
                    if new_exp > old_exp:
                        dyn[i][new_probs] = new_exp,old_sol+new_play
                else:
                    dyn[i][new_probs] = new_exp, old_sol + new_play

    max_exp = 0
    max_sol =""
    for prob in dyn[60]:
        this_exp, this_sol = dyn[60][prob]
        if this_exp > max_exp:
            max_exp = this_exp
            max_sol = this_sol

    return max_sol, max_exp


def get_exp(probs, new_play,i, W, E):
    winner = {"P":"S", "R":"P", "S":"R"}
    exp = 0
    for dyn_i, enemy_play in enumerate(["R", "P", "S"]):
        enemy_play = winner[enemy_play]
        if new_play == enemy_play:
            exp += probs[dyn_i]/(i-1)*E
        if new_play == winner[enemy_play]:
            exp += probs[dyn_i]/(i-1)*W
    return exp

def test_str(S, W, E):
    rounds = 60
    winner = {"P": "S", "R": "P", "S": "R"}
    counts = {"P": 0, "S": 0, "R": 0}
    sol_s = ""
    exp = 0
    assert len(S) == rounds
    for i,s in enumerate(S):
        if i == 0:
            exp += 1 / 3 * W + 1 / 3 * E
        else:
            for enemy_play in ["R", "P", "S"]:

                if s == winner[winner[enemy_play]]:
                    exp += counts[enemy_play] / i * W
                if s == winner[enemy_play]:
                    exp+=counts[enemy_play] / i * E

        sol_s = sol_s + s
        counts[s] = counts[s] + 1
    return exp

