import random
cnt = 0
hashing = {}
primes = []

def cal(exp, index):
    global cnt, hashing, primes
    left, right = 0, 0
    index += 1
    if exp[index] == '(':
        left, index = cal(exp, index)
    else:
        while exp[index].isdigit() == True:
            left = left * 10 + int(exp[index])
            index += 1

    op = exp[index]
    index += 1
    if exp[index] == '(':
        right, index = cal(exp, index)
    else:
        while exp[index].isdigit() == True:
            right = right * 10 + int(exp[index])
            index += 1

    index += 1
    result = 0
    if op == '+':
        result = left + right
    elif op == '*':
        result = left * right
    else:
        key = str(left) + op + str(right)
        if hashing.get(key, None) == None:
            hashing[key] = primes[cnt]
            cnt += 1
        result = hashing[key]
    return (result, index) 

