from bisect import bisect_left

T = int(input())
for case in range(1, T + 1):
    N, M = (int(i) for i in input().split())
    ranges = []
    skills = []
    for _ in range(N):
        ranges.append(tuple(int(i) for i in input().split()))
    skills = [int(i) for i in input().split()]
    ranges.sort()

    out = []
    for skill in skills:
        location = bisect_left(ranges, (skill, float('inf')))
        if location == 0:
            out.append(ranges[0][0])
            if ranges[0][0] == ranges[0][1]:
                ranges.pop(0)
            else:
                ranges[0] = (ranges[0][0] + 1, ranges[0][1])
        elif location == len(ranges) and skill > ranges[-1][1]:
            out.append(ranges[-1][1])
            if ranges[-1][0] == ranges[-1][1]:
                ranges.pop()
            else:
                ranges[-1] = (ranges[-1][0], ranges[-1][1] - 1)
        elif ranges[location - 1][1] >= skill:  # inside ranges[location - 1]
            out.append(skill)
            left, right = ranges[location - 1]
            if skill == left and skill == right:
                ranges.pop(location - 1)
            elif skill == left:
                ranges[location - 1] = (left + 1, right)
            elif skill == right:
                ranges[location - 1] = (left, right - 1)
            else:
                ranges[location - 1] = (left, skill - 1)
                ranges.insert(location, (skill + 1, right))
        else:  # between location - 1 and location
            if skill - ranges[location - 1][1] <= ranges[location][0] - skill:
                out.append(ranges[location - 1][1])
                if ranges[location - 1][0] == ranges[location - 1][1]:
                    ranges.pop(location - 1)
                else:
                    ranges[location - 1] = (ranges[location - 1][0], ranges[location - 1][1] - 1)
            else:
                out.append(ranges[location][0])
                if ranges[location][0] == ranges[location][1]:
                    ranges.pop(location)
                else:
                    ranges[location] = (ranges[location][0] + 1, ranges[location][1])

    print(f'Case #{case}: {" ".join(str(i) for i in out)}')

