def YesNo(cond):
    CP(cond, 'Yes', 'No')
def RS():
    return sys.stdin.readline().strip()
def RI():
    return int(RS())
def RVI():
    return [int(n) for n in RS().split()]
def WVI(arr, sep=' ', **kwargs):
    print(sep.join([str(a) for a in arr]), **kwargs)

def cuts(L, K):
    return (L + K - 1) // K  # ceil(L / K)

def impl(R, C, K):
    if R > C:
        R, C = C, R

    if R == 0:
        res = 0
    elif C <= K:
        res =R * C - 1
    else:
        D = C // K
        res = D * ((R - 1) + (K - 1) * R + cuts(R, K))
        if C % K == 0:
            res -= cuts(R, K)
        else:
            res += impl(C - D * K, R, K)
    #print(R, C, K, res)
    return res

def solve(R, C, K, r1, c1, r2, c2):
    # print('s', r1, c1, r2, c2)
    L = 0
    if c1 != 0:
        L += cuts(r2, K)
    if c2 != C:
        L += cuts(r2 - r1, K)
    if r1 != 0:
        L += cuts(c2 - c1, K)
    if r2 != R:
        L += cuts(c2 - c1, K)
    #print(L)
    return impl(r2-r1, c2-c1, K) + L

# horizontal flip
def solve2(R, C, K, r1, c1, r2, c2):
    return min(solve(R, C, K, r1, c1, r2, c2),
               solve(R, C, K, r1, C-c2, r2, C-c1))

# vertical flip
def solve1(R, C, K, r1, c1, r2, c2):
    return min(solve2(R, C, K, r1, c1, r2, c2),
               solve2(R, C, K, R-r2, c1, R-r1, c2))

