import os, sys

def find_distance(h):
    # print(h)
    # h = h.split(' ')

    left_array = [0] * len(h)
    left_array[0] = -1 if h[0] == '0' else 1
    for i in range(1,len(h)):
        if h[i] == '1':
            left_array[i] = i+1
        else:
            left_array[i] = left_array[i-1]

    right_array = [0] * len(h)
    right_array[-1] = -1 if h[-1] == '0' else len(h)
    for j in range(len(h)-2,-1,-1):
        if h[j] == '1':
            right_array[j] = j+1
        else:
            right_array[j] = right_array[j+1]

    ans = [0] * len(left_array)
    for k in range(len(ans)):
        if left_array[k] != -1 and right_array[k] != -1:
            ans[k] = min(abs(k+1-left_array[k]), abs(k+1-right_array[k]))
        elif left_array[k] != -1:
            ans[k] = abs(k+1-left_array[k])
        else:
            ans[k] = abs(k+1-right_array[k])

    return sum(ans)


