def intinp():
    x = input()
    if ' ' in x:
        return tuple(int(z) for z in x.split(" "))
    return int(x)

def can_conn(conn, already_broken_rooms, pts_already, rooms, room_no):
    if room_no not in conn.keys():
        return False
    for connected_room_no in conn[room_no]:
        if (1 << connected_room_no) & already_broken_rooms and rooms[room_no][0] <= pts_already <= rooms[room_no][1]:
            return True
    return False

# return number of ways you can get to K points starting from already_broken_rooms
def rec(already_broken_rooms, pts_already, N, conn, memo, rooms, K):
    res = 0
    for room_no in range(N):
        if (1 << room_no) & already_broken_rooms:
            # room already broken
            continue

        # can we enter this room?
        if not can_conn(conn, already_broken_rooms, pts_already, rooms, room_no):
            continue

        # have we entered this room already in a parallel universe?
        new_broken_rooms = already_broken_rooms | (1 << room_no)
        if new_broken_rooms in memo.keys():
            res += memo[new_broken_rooms]
            continue

        # if not then it's our turn
        # if we get K points then the search ends
        if pts_already + rooms[room_no][2] == K:
            res += 1
            memo[new_broken_rooms] = 1

        else:
            room_res = rec(new_broken_rooms, pts_already + rooms[room_no][2], N, conn, memo, rooms, K)
            memo[new_broken_rooms] = room_res
            res += room_res

    return res


def do_case(case_no):
    N, M, K = intinp()
    conn = {}
    memo = { 0x0: 0 } # (broken) -> no_of_ways_to_get_to_this_state
    rooms = [intinp() for i in range(N)] # L, R, A
    for j in range(M):
        X, Y = intinp()
        conn[X] = [Y] if X not in conn.keys() else conn[X] + [Y]
        conn[Y] = [X] if Y not in conn.keys() else conn[Y] + [X]

    res = 0
    for starting_room_no in range(N):
        broken = 1 << starting_room_no
        res += rec(broken, rooms[starting_room_no][2], N, conn, memo, rooms, K)

    for room_no in range(N):
        if rooms[room_no][2] == K:
            res += 1
    return res


number_of_cases = intinp()
for case_no in range(1, number_of_cases + 1):
    result = do_case(case_no)
    print(f"Case #{case_no}: {result}")

