from collections import defaultdict

for tInd in range (int(input())):
    ans = float('inf')
    n,k = [int(i) for i in input().split()]
    a = [int(i) for i in input().split()]
    if sum(a)<k:
        ans = -1
        print("Case #"+str(tInd+1)+":",ans)
        continue
    ps = [0]+a[:]
    for i in range (1,n+1):
        ps[i] += ps[i-1]
    dic = defaultdict(lambda: float('inf'))
    for i in range (n):
        for j in range (i):
            cs = ps[i] - ps[j]
            if cs<=k:
                dic[cs] = min(dic[cs], i-j)
        for j in range (i,n):
            if j-i+1>ans:
                break
            cans = j-i+1
            cs = ps[j+1]-ps[i]
            if cs>k:
                continue
            if cs==k:
                ans = min(ans,j-i+1)
                continue
            if k-cs in dic:
                cans += dic[k-cs]
                ans = min(ans, cans)

    if ans > 10**9:
        ans = -1
    print("Case #"+str(tInd+1)+":",ans)

