        s=f.readline().strip()
        if s:
            return s
def read_list(f):
    return [int(x) for x in read_line(f).split()]
def read_tuple(f):
    return tuple(read_list(f))

def load_single_case(f):
    return read_tuple(f)


def load_cases(f):
    n=int(f.readline())
    cases=[]
    for _ in range(n):
        yield load_single_case(f)
    return cases




def solve_odd(N, A):
    nbase=(N-1)//2
    if A<nbase*2-1:
        return None
    poly=[]
    for i in range(nbase):
        poly.append((i%2,i))
    poly.append((1,A-nbase+1))
    for i in range(nbase-1,-1,-1):
        poly.append((i%2+1,i))
    return poly
def solve_even(N, A):
    nbase=(N-2)//2
    if A<nbase*2:
        return None
    poly=[]
    for i in range(nbase):
        poly.append((i%2,i))
    poly.append(((nbase-1)%2,A-nbase))
    poly.append(((nbase-1)%2+1,nbase))
    for i in range(nbase-1,-1,-1):
        poly.append((i%2+1,i))
    return poly

def solve(case):
    N,A=case
    if N%2==1:
        return solve_odd(N,A)
    else:
        return solve_even(N,A)






def outcome_string(outcome):
    if outcome is None:
        return "IMPOSSIBLE"
    return "POSSIBLE\n"+"\n".join("{} {}".format(*p) for p in outcome)


def save_outcomes(f, outcomes):
    for n,o in enumerate(outcomes):
        f.write("Case #{0}: {1}\n".format( n+1 , outcome_string(o) ))
def process(path_in=None, path_out=None):
    if path_out is None and path_in is not None:
        path_out=path_in.rsplit(".",1)[0]+".out"
    f_in=open(path_in) if path_in else sys.stdin
    f_out=open(path_out,"w") if path_out else sys.stdout
    try:
        outcomes=[solve(c) for c in load_cases(f_in)]
        save_outcomes(f_out, outcomes)
    finally:
        if path_in:
            f_in.close()
        if path_out:
            f_out.close()


