from collections import deque

def candidates(arr, k):
    if k == 0:
        return arr
    res = []
    for elt in arr:
        i = elt.index('?')
        res += [elt[:i] + '0' + elt[i+1:], elt[:i] + '1' + elt[i + 1:]]
    return candidates(res, k - 1)

def is_palin(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] == s[j]:
            i += 1
            j -= 1
        else:
            return False
    return True

def has_palin(s):
    if is_palin(s[:5]) or is_palin(s[1:6]) or is_palin(s):
        return True
    return False

has_palins = [False for _ in range(1 << 6)]  # 6 binary digits that are palindrome
for p in candidates(['??????'], 6):
    has_palins[int(p, 2)] = has_palin(p)

def define_new(s, i):
    now = s + S[i + 5]  # length 6

    k = now.count('?')
    res = []
    # make length 6 none-palindrome
    for e in candidates([now], k):
        if not has_palins[int(e, 2)]:  # e is length 6.
            res.append(e[1:])  # length 5
    return res

def main():
    len_S = len(S)
    if len_S < 5:
        return "POSSIBLE"
    if len_S == 5:
        k = S.count('?')
        for e in candidates([S], k):
            if not is_palin(e):
                return "POSSIBLE"
    q = deque([S[:5]])
    end = len_S - 5
    i = 0
    while q and i < end:
        length = len(q)
        for _ in range(length):
            s = q.popleft()
            for e in define_new(s, i):
                q.append(e)
        i += 1
    if q:
        for e in q:
            if not is_palin(e):
                return "POSSIBLE"
    return "IMPOSSIBLE"

