import os
import sys
from io import BytesIO, IOBase
from math import gcd
from collections import defaultdict

def calc(n):
    if n == 0:
        return 0
    cnt = 0
    if n == (10 ** 12):
        n -= 1
        cnt += 1
    nL = []
    while n:
        nL.append(n % 10)
        n //= 10
    nL.reverse()
    def joiner(a,b,c,d):
        return a << 22 | b << 12 | c << 1 | d
    def splitter(x):
        a = x >> 22
        x ^= (a << 22)
        b = x >> 12
        x ^= (b << 12)
        c = x >> 1
        x ^= c << 1
        return a,b,c,x
    for summ in range(1, len(nL) * 9 + 1):
        dp = defaultdict(int)
        dp[joiner(summ, summ, 0, 0)] = 1
        for i in range(len(nL)):
            newdp = defaultdict(int)
            for elem2 in dp:
                for j in range(10):
                    elem = splitter(elem2)
                    if elem[2] == 0 and j > nL[i]:
                        continue
                    nextElem = (elem[0] - j, elem[1] // gcd(elem[1], j) if j != 0 or elem[3] else elem[1], elem[2] or j < nL[i], elem[3] or j != 0)
                    if nextElem[0] < 0 or nextElem[0] > 9 * (len(nL) - i - 1):
                        continue
                    newdp[joiner(*nextElem)] += dp[elem2]
            dp = newdp
        for elem2 in dp:
            elem = splitter(elem2)
            if elem[0] == 0 and elem[1] == 1:
                cnt += dp[elem2]
    return cnt

def main():
    for t in range(int(input())):
        a,b = map(int,input().split())
        print(f"Case #{t + 1}: {calc(b) - calc(a - 1)}")


