def min_dist(dp, left, right, x):
    new_dp = [INF]*len(dp)
    for i, d in enumerate(dp):
        if d == INF:
            continue
        for j in [left[i*MAX_S+(x-1)], right[i*MAX_S+(x-1)]]:
            if j != -1:
                new_dp[j] = min(new_dp[j], d+abs(j-i))
    return new_dp

def solution():
    N = int(input())
    S = list(map(int, input().split()))
    M = int(input())
    K = list(map(int, input().split()))
    lookup = [[] for _ in range(MAX_S+1)]
    left = [-1]*(MAX_M*MAX_S)
    for i in range(M):
        lookup[K[i]].append(i)
        for x, js in enumerate(lookup):
            if js: left[i*MAX_S+(x-1)] = js[-1]
    lookup = [[] for _ in range(MAX_S+1)]
    right = [-1]*(MAX_M*MAX_S)
    for i in reversed(range(M)):
        lookup[K[i]].append(i)
        for x, js in enumerate(lookup):
            if js: right[i*MAX_S+(x-1)] = js[-1]
    dp = [INF]*M
    for i in lookup[S[0]]:
        dp[i] = 0
    for i in range(1, N):
        dp = min_dist(dp, left, right, S[i])
    return min(dp)

