def Divisors(n):
    i = 1
    ans = []
    while (i * i < n):
        if (n % i == 0):
            ans.append(i)

        i += 1

    for i in range(int(sqrt(n)), 0, -1):
        if (n % i == 0):
            ans.append(n // i)

    return ans

