def isval(s):
    n = len(s)
    d = defaultdict(bool)

    if n == 1:
        return True

    if s[0] != s[1]:
        d[s[0]] = True

    for i in range(1, n):
        if s[i] != s[i - 1]:
            if d[s[i]]:
                return False
            d[s[i]] = True

    return True

class Point:
    def __init__(self, x, l1):
        self.x = x
        self.l1 = l1

    def __lt__(self, b):
        return self.l1[self.x] < self.l1[b.x]

    def getval(self):
        return self.x

def chck(n, l):
    ans = 0
    for i in range(n - 1):
        ans += l[i] ^ l[i + 1]
    return ans

