def panda(n, l):
    d = defaultdict(int)
    for i in l:
        d[i] += 1
    l1 = sorted(l)
    ans = []
    for i in l:
        j = bisect_left(l1, 2 * i)
        j = min(j, n - 1)
        # print(i, j, l1, d[i])
        if l1[j] == i:
            if d[i] < 2:
                j -= 1
        if l1[j] > 2 * i:
            j -= 1
            if l1[j] <= 2 * i:
                if l1[j] == i:
                    if d[i] < 2:
                        j -= 1
                if j == -1:
                    ans.append(-1)
                else:
                    ans.append(l1[j])
            else:
                ans.append(-1)
        else: 
            ans.append(l1[j])
    # print(ans)
    return ans


