from heapq import heappop, heappush

def solve():
    D, N, X = map(int, input().split())
    q = []
    for _ in range(N):
        Q, L, V = map(int, input().split())
        q.append((L, V, Q))
    q.sort()
    q1 = []
    res = 0
    t = 0
    while t < D and (q or q1):
        if not q1:
            t = q[0][0]
        while q and q[0][0] <= t:
            _, v, y = heappop(q)
            heappush(q1, (-v, y))
        t1 = q[0][0] if q else D
        x = X
        while t < t1 and x and q1:
            nv, y = heappop(q1)
            v = -nv
            if y >= x:
                if x == X:
                    h = min(t1 - t, y // x)
                    m = x * h
                    if y > m:
                        heappush(q1, (nv, y-m))
                    res += v * m
                    t += h
                else:
                    res += v * x
                    if y > x:
                        heappush(q1, (nv, y-x))
                    t += 1
                x = X
            else:
                x -= y
                res += v * y
    return res

for i in range(int(input())):
    res = solve()
    print(f'Case #{i+1}:', res)

