import math
def distance_to_center(rs,x,y):
    return math.sqrt(x ** 2 + y ** 2) - rs

def get_points(rs,rh,red,yellow):
    r_house = []
    y_house = []
    for ball in red:
        x,y = ball
        d = distance_to_center(rs,x,y)
        if d <= rh:
            r_house.append(d)
    for ball in yellow:
        x,y = ball
        d = distance_to_center(rs,x,y)
        if d <= rh:
            y_house.append(d)
    r_house.sort()
    y_house.sort()
    while len(r_house) != 0 and len(y_house) != 0:
        if r_house[-1] < y_house[-1]:
            y_house.pop()
        else:
            r_house.pop()
    points_red = len(r_house)
    point_yellow = len(y_house)
    return points_red, point_yellow




