    tests = input()
    for i in range(int(tests)):
        Rs,Rh = [int(x) for x in input().split(' ')]
        stones_red = int(input())
        red = []
        for k in range(stones_red):
            red.append([int(x) for x in input().split(' ')])
        stones_yellow = int(input())
        yellow = []
        for k in range(stones_yellow):
            yellow.append([int(x) for x in input().split(' ')])
        score_red, score_yellow = get_points(Rs,Rh,red,yellow)
        print(f'Case #{i+1}: {score_red} {score_yellow}')

