    main()

from heapq import heappush, heappop

casecnt = int(input())
for case in range(casecnt):
    l = int(input())

    # Start backwards from L:
    # 1c = -1
    # 6c = 1/2
    # 8c = 1/3
    # 10c = 1/4 ... etc

    best = l
    q = []
    heappush(q,(l,0))
    memo = {}    

    while q:
        #print(q, best)
        ll,cc = heappop(q)
        if ll not in memo:
            memo[ll] = cc
        else:
            if cc<memo[ll]:
                memo[ll] = cc
            else:
                continue

        if cc < best:
            if ll<=6:
                best = min(best,cc+ll)
            else:
                heappush(q,(ll-1,cc+1))
                c = 4
                for m in range(2,(ll//2+2)):
                    c += 2
                    if cc+c<best:
                        if ll%m==0:
                            heappush(q,(ll//m,cc+c))
                    else:
                        break

    print("Case #{}: {}".format(case+1,best))

import sys

sys.setrecursionlimit(10**6)

def sol(s, adj, memo):
    if memo.get(s, None) is not None:
        return memo[s]
    if len(adj[s]) == 0:
        memo[s] = 1
        return 1
    else:
        total = 1
        for el in adj[s]:
            total += sol(el, adj, memo)
        memo[s] = total
        return total


if __name__ == "__main__":
    t = int(input())
    for k in range(1, t + 1):
        n = int(input())
        adj = [[] for _ in range(n)]
        cap = list(map(int, input().strip().split()))
        for _ in range(n - 1):
            temp = list(map(lambda x: x - 1, map(int, input().strip().split())))
            if cap[temp[0]] > cap[temp[1]]:
                adj[temp[0]].append(temp[1])
            elif cap[temp[0]] < cap[temp[1]]:
                adj[temp[1]].append(temp[0])
        m = 0
        memo = {}
        for s in range(n):
            val = sol(s, adj, memo)
            if val > m:
                m = val
        print(f"Case #{k}: {m}")
